  ('coprosma-crassifolia', 'Coprosma crassifolia', null, null, null, 'core', true, false, false, null, false, 'SP-043', null, '{"commonName":"Thick-leaved coprosma","maoriNames":["Mingimingi"],"nameNote":"Mingimingi is shared with other small-leaved shrubs, so it does not uniquely identify this species.","summary":"A much-branched native shrub found in scrub, forest and coastal country. Its translucent berries attract birds and skinks.","lookFor":"Small, stiff, rounded leaves in opposite pairs, spaced along the branches. They are glossy dark green above and pale underneath.","sources":[{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Coprosma_crassifolia"},{"label":"Wikipedia · shared Māori names","url":"https://en.wikipedia.org/wiki/Coprosma_propinqua"}],"checkedOn":"2026-10-04"}'::jsonb, '[{"src":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/12/Coprosma_crassifolia_11.JPG/960px-Coprosma_crassifolia_11.JPG","width":960,"height":720,"caption":"Coprosma crassifolia at Whitireia Reserve, Porirua.","author":"Rudolph89","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Coprosma_crassifolia_11.JPG","articleUrl":"https://en.wikipedia.org/wiki/Coprosma_crassifolia","retrievedAt":"2026-10-03","focalPoint":"50% 50%","sourceName":"Wikimedia Commons"},{"src":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5a/Coprosma_crassifolia_in_Auckland_Botanic_Gardens_01.jpg/960px-Coprosma_crassifolia_in_Auckland_Botanic_Gardens_01.jpg","width":960,"height":640,"caption":"Coprosma crassifolia in Auckland Botanic Gardens, Manurewa, South Auckland, New Zealand","author":"Krzysztof Golik","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Coprosma_crassifolia_in_Auckland_Botanic_Gardens_01.jpg","articleUrl":"https://en.wikipedia.org/wiki/Coprosma_crassifolia","retrievedAt":"2026-10-03","focalPoint":"50% 50%","sourceName":"Wikimedia Commons"},{"src":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/dd/Coprosma_crassifolia_kz2.jpg/960px-Coprosma_crassifolia_kz2.jpg","width":960,"height":1440,"caption":"Coprosma crassifolia in Auckland Botanic Gardens","author":"Krzysztof Ziarnek, Kenraiz","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Coprosma_crassifolia_kz2.jpg","articleUrl":"https://en.wikipedia.org/wiki/Coprosma_crassifolia","retrievedAt":"2026-10-03","focalPoint":"50% 50%","sourceName":"Wikimedia Commons"}]'::jsonb),
  ('coprosma-dumosa', 'Coprosma dumosa', null, null, null, 'core', false, false, false, null, false, 'SP-044', null, '{"commonName":"Mingimingi","maoriNames":["Mingimingi"],"nameNote":"Mingimingi is shared with several other small-leaved shrubs and does not uniquely identify this species.","summary":"A bushy native shrub with a layered branching pattern. It is common in montane forest and shrubland, including wetter regions and parts of the drier South Island.","lookFor":"Small, thick oval leaves clustered in opposite pairs along short branchlets. Tiny pits occur underneath the leaves. Ripe fruit can be orange, red or translucent white.","sources":[{"label":"NZPCN","url":"https://www.nzpcn.org.nz/flora/species/coprosma-dumosa/"},{"label":"Wikipedia · shared Māori name","url":"https://en.wikipedia.org/wiki/Coprosma_propinqua"}],"checkedOn":"2026-10-04"}'::jsonb, '[{"src":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/ff/Coprosma_dumosa_kz1.jpg/960px-Coprosma_dumosa_kz1.jpg","width":960,"height":661,"caption":"Coprosma dumosa in Aoraki Mt Cook Village, Canterbury (New Zealand).","author":"Krzysztof Ziarnek, Kenraiz","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Coprosma_dumosa_kz1.jpg","articleUrl":"https://en.wikipedia.org/wiki/Coprosma_propinqua","retrievedAt":"2026-10-04","focalPoint":"50% 50%","sourceName":"Wikimedia Commons"},{"src":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/ba/Coprosma_dumosa_kz2.jpg/960px-Coprosma_dumosa_kz2.jpg","width":960,"height":640,"caption":"Coprosma dumosa in Aoraki Mt Cook Village, Canterbury (New Zealand).","author":"Krzysztof Ziarnek, Kenraiz","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Coprosma_dumosa_kz2.jpg","articleUrl":"https://en.wikipedia.org/wiki/Coprosma_propinqua","retrievedAt":"2026-10-04","focalPoint":"50% 50%","sourceName":"Wikimedia Commons"},{"src":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7d/Coprosma_dumosa_%28Cheeseman%29_G.T.Jane_%28AM_AK360802%29.jpg/960px-Coprosma_dumosa_%28Cheeseman%29_G.T.Jane_%28AM_AK360802%29.jpg","width":960,"height":1511,"caption":"Coprosma dumosa herbarium specimen AK360802, Auckland Museum (preserved specimen, not a living plant).","author":"Cam Kilgour / Auckland Museum","license":"CC BY 4.0","licenseUrl":"https://creativecommons.org/licenses/by/4.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Coprosma_dumosa_(Cheeseman)_G.T.Jane_(AM_AK360802).jpg","articleUrl":"https://en.wikipedia.org/wiki/Coprosma_propinqua","retrievedAt":"2026-10-04","focalPoint":"50% 50%","sourceName":"Wikimedia Commons"}]'::jsonb),
