  ('coprosma-intertexta', 'Coprosma intertexta', null, null, null, 'core', false, true, true, null, false, 'SP-046', null, '{"commonName":null,"maoriNames":[],"summary":"A twiggy native shrub of the eastern South Island, often found in dry scrub and rocky places. It can spread by suckering to form thickets.","lookFor":"Very narrow, needle-like leaves, sometimes curved sideways, among reddish, widely branching twigs. Ripe fruit is small and white or pale blue.","sources":[{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Coprosma_intertexta"},{"label":"NZPCN","url":"https://www.nzpcn.org.nz/flora/species/coprosma-intertexta/"}],"checkedOn":"2026-10-04"}'::jsonb, '[{"src":"https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c6/Coprosma_intertexta_1.jpg/960px-Coprosma_intertexta_1.jpg","width":960,"height":640,"caption":"Coprosma intertexta in Dunedin Botanic Garden, Dunedin, New Zealand.","author":"Krzysztof Golik","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Coprosma_intertexta_1.jpg","articleUrl":"https://en.wikipedia.org/wiki/Coprosma_intertexta","retrievedAt":"2026-10-04","focalPoint":"50% 50%","sourceName":"Wikimedia Commons"},{"src":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fa/Coprosma_intertexta_11.JPG/960px-Coprosma_intertexta_11.JPG","width":960,"height":720,"caption":"Coprosma intertexta, at Otari-Wilton''s Bush, Wellington, New Zealand.","author":"Rudolph89","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Coprosma_intertexta_11.JPG","articleUrl":"https://en.wikipedia.org/wiki/Coprosma_intertexta","retrievedAt":"2026-10-04","focalPoint":"50% 50%","sourceName":"Wikimedia Commons"},{"src":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9d/Coprosma_intertexta_2.jpg/960px-Coprosma_intertexta_2.jpg","width":960,"height":729,"caption":"Coprosma intertexta in Dunedin Botanic Garden, Dunedin, New Zealand.","author":"Krzysztof Golik","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Coprosma_intertexta_2.jpg","articleUrl":"https://en.wikipedia.org/wiki/Coprosma_intertexta","retrievedAt":"2026-10-04","focalPoint":"50% 50%","sourceName":"Wikimedia Commons"}]'::jsonb),
  ('coprosma-linariifolia', 'Coprosma linariifolia', null, null, null, 'core', true, false, false, null, false, 'SP-047', null, '{"commonName":"Yellow wood","maoriNames":["Mikimiki"],"nameNote":"Mikimiki is a shared name for several small-leaved shrubs; it does not uniquely identify this species.","summary":"A native shrub or small tree found in forest and scrub from the central North Island southward. Its inner wood is yellow, giving rise to its English common name.","lookFor":"Pairs of narrow leaves on dark, fuzzy twigs. The leaves are paler underneath, and ripe fruit is white with blue flecks.","sources":[{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Coprosma_linariifolia"},{"label":"New Zealand Plant Conservation Network","url":"https://www.nzpcn.org.nz/flora/species/coprosma-linariifolia/"}],"checkedOn":"2026-10-04"}'::jsonb, '[{"src":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/66/Coprosma_linariifolia_11.JPG/960px-Coprosma_linariifolia_11.JPG","width":960,"height":720,"caption":"Coprosma linariifolia, at Otari-Wilton''s Bush, Wellington, New Zealand.","author":"Rudolph89","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Coprosma_linariifolia_11.JPG","articleUrl":"https://en.wikipedia.org/wiki/Coprosma_linariifolia","retrievedAt":"2026-10-04","focalPoint":"50% 50%","sourceName":"Wikimedia Commons"},{"src":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/74/Coprosma_linariifolia_kz01.jpg/960px-Coprosma_linariifolia_kz01.jpg","width":960,"height":1440,"caption":"Coprosma linariifolia in Dunedin Botanic Garden.","author":"Krzysztof Ziarnek, Kenraiz","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Coprosma_linariifolia_kz01.jpg","articleUrl":"https://en.wikipedia.org/wiki/Coprosma_linariifolia","retrievedAt":"2026-10-04","focalPoint":"50% 50%","sourceName":"Wikimedia Commons"},{"src":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/69/Coprosma_linariifolia_Hook.f._%28AM_AK362659%29.jpg/960px-Coprosma_linariifolia_Hook.f._%28AM_AK362659%29.jpg","width":960,"height":1365,"caption":"Coprosma linariifolia herbarium specimen AK362659, Auckland Museum (preserved specimen, not a living plant).","author":"A E Esler / Auckland Museum","license":"CC BY 4.0","licenseUrl":"https://creativecommons.org/licenses/by/4.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Coprosma_linariifolia_Hook.f._(AM_AK362659).jpg","articleUrl":"https://en.wikipedia.org/wiki/Coprosma_linariifolia","retrievedAt":"2026-10-04","focalPoint":"50% 50%","sourceName":"Wikimedia Commons"}]'::jsonb),
  ('coprosma-lucida', 'Coprosma lucida', null, 'Karamū', 'Karamū', 'core', true, false, false, null, false, 'SP-048', null, '{"commonName":"Shining karamū","maoriNames":["Karamū","Kāramuramu"],"nameNote":"Karamū is shared by several Coprosma species. Shining karamū and the botanical name help distinguish this one.","summary":"A native shrub or small tree with much larger leaves than the twiggy coprosmas. Its bright, glossy foliage can make it look similar to other broad-leaved shrubs.","lookFor":"Opposite pairs of glossy oval leaves, dark green above and paler below. The central leaf vein is raised on the upper surface, unlike the indented vein of Coprosma robusta.","sources":[{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Coprosma_lucida"}],"checkedOn":"2026-10-04"}'::jsonb, '[{"src":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/28/Coprosma_lucida_in_Mount_Aspiring_National_Park_01.jpg/960px-Coprosma_lucida_in_Mount_Aspiring_National_Park_01.jpg","width":960,"height":726,"caption":"Coprosma lucida in Mount Aspiring National Park, South Island of New Zealand.","author":"Krzysztof Golik","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Coprosma_lucida_in_Mount_Aspiring_National_Park_01.jpg","articleUrl":"https://en.wikipedia.org/wiki/Coprosma_lucida","retrievedAt":"2026-10-04","focalPoint":"50% 50%","sourceName":"Wikimedia Commons"},{"src":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0f/Coprosma_lucida_in_Mount_Aspiring_National_Park_02.jpg/960px-Coprosma_lucida_in_Mount_Aspiring_National_Park_02.jpg","width":960,"height":750,"caption":"Leaves of Coprosma lucida in Mount Aspiring National Park, South Island of New Zealand.","author":"Krzysztof Golik","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Coprosma_lucida_in_Mount_Aspiring_National_Park_02.jpg","articleUrl":"https://en.wikipedia.org/wiki/Coprosma_lucida","retrievedAt":"2026-10-04","focalPoint":"50% 50%","sourceName":"Wikimedia Commons"},{"src":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ed/Coprosma_lucida_11.JPG/960px-Coprosma_lucida_11.JPG","width":960,"height":686,"caption":"Coprosma lucida, karamu, a young plant with fruit in Upper Hutt, New Zealand.","author":"Rudolph89","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Coprosma_lucida_11.JPG","articleUrl":"https://en.wikipedia.org/wiki/Coprosma_lucida","retrievedAt":"2026-10-04","focalPoint":"50% 50%","sourceName":"Wikimedia Commons"}]'::jsonb),
