  ('coprosma-propinqua', 'Coprosma propinqua', null, 'Mingimingi', 'Mingimingi', 'core', true, false, false, null, false, 'SP-050', null, '{"commonName":"Black scrub","maoriNames":["Mingimingi","Mikimiki"],"nameNote":"Mikimiki is a Kāi Tahu form. These names are shared with several other small-leaved shrubs.","summary":"A native shrub or small tree with a dense network of spreading branches. It grows in forest, scrub, wetlands and beside streams throughout much of New Zealand.","lookFor":"Tiny, narrow dark-green leaves on tangled twigs. Ripe berries are often blue or blue-flecked, although their colour varies.","sources":[{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Coprosma_propinqua"}],"checkedOn":"2026-10-04"}'::jsonb, '[{"src":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/15/Coprosma_propinqua_11.JPG/960px-Coprosma_propinqua_11.JPG","width":960,"height":720,"caption":"Coprosma propinqua with fruit at Zealandia, Wellington.","author":"Rudolph89","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Coprosma_propinqua_11.JPG","articleUrl":"https://en.wikipedia.org/wiki/Coprosma_propinqua","retrievedAt":"2026-10-03","focalPoint":"50% 50%","sourceName":"Wikimedia Commons"},{"src":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7c/Coprosma_propinqua_in_Auckland_Botanic_Gardens.jpg/960px-Coprosma_propinqua_in_Auckland_Botanic_Gardens.jpg","width":960,"height":640,"caption":"Coprosma propinqua in Auckland Botanic Gardens, Manurewa, South Auckland, New Zealand","author":"Krzysztof Golik","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Coprosma_propinqua_in_Auckland_Botanic_Gardens.jpg","articleUrl":"https://en.wikipedia.org/wiki/Coprosma_propinqua","retrievedAt":"2026-10-03","focalPoint":"50% 50%","sourceName":"Wikimedia Commons"},{"src":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/30/Coprosma_propinqua_12.jpg/960px-Coprosma_propinqua_12.jpg","width":960,"height":720,"caption":"Coprosma propinqua, photographed in Pauatahanui Wildlife Reserve, Porirua, Wellington","author":"Rudolph89","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Coprosma_propinqua_12.jpg","articleUrl":"https://en.wikipedia.org/wiki/Coprosma_propinqua","retrievedAt":"2026-10-03","focalPoint":"50% 50%","sourceName":"Wikimedia Commons"}]'::jsonb),
