  ('coprosma-rigida', 'Coprosma rigida', null, null, null, 'core', false, false, false, null, false, 'SP-053', null, '{"commonName":null,"maoriNames":[],"summary":"A bushy native coprosma with widely spreading branches. Its small paired leaves grow in clusters, while older twigs develop a conspicuous orange or reddish colour.","lookFor":"Tiny oval leaves, often widest near a slightly dented tip, with reddish margins. Young twigs are fuzzy; older ones are shiny orange or red. Fruit is yellow.","sources":[{"label":"NZPCN","url":"https://www.nzpcn.org.nz/flora/species/coprosma-rigida/"}],"checkedOn":"2026-10-04"}'::jsonb, '[{"src":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9b/Coprosma_rigida_1.jpg/960px-Coprosma_rigida_1.jpg","width":960,"height":640,"caption":"Coprosma rigida in Dunedin Botanic Garden, Dunedin, New Zealand.","author":"Krzysztof Golik","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Coprosma_rigida_1.jpg","articleUrl":"https://en.wikipedia.org/wiki/Coprosma_rigida","retrievedAt":"2026-10-04","focalPoint":"50% 50%","sourceName":"Wikimedia Commons"},{"src":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/40/Coprosma_rigida_11.JPG/960px-Coprosma_rigida_11.JPG","width":960,"height":720,"caption":"Coprosma rigida, on Hutt river bank, Moonshine, Upper Hutt, New Zealand.","author":"Rudolph89","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Coprosma_rigida_11.JPG","articleUrl":"https://en.wikipedia.org/wiki/Coprosma_rigida","retrievedAt":"2026-10-04","focalPoint":"50% 50%","sourceName":"Wikimedia Commons"},{"src":"https://thumb.wikimedia.org/wikipedia/commons/thumb/c/cc/Coprosma_rigida_2.jpg/960px-Coprosma_rigida_2.jpg","width":960,"height":640,"caption":"Coprosma rigida in Dunedin Botanic Garden, Dunedin, New Zealand.","author":"Krzysztof Golik","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Coprosma_rigida_2.jpg","articleUrl":"https://en.wikipedia.org/wiki/Coprosma_rigida","retrievedAt":"2026-10-04","focalPoint":"50% 50%","sourceName":"Wikimedia Commons"}]'::jsonb),
  ('coprosma-rotundifolia', 'Coprosma rotundifolia', null, null, null, 'core', true, false, false, null, false, 'SP-054', null, '{"commonName":null,"maoriNames":[],"summary":"An endemic shrub or small tree of streamside forest and shrubland. Slender spreading branches carry rounded leaves that may be blotched brown or purple.","lookFor":"Opposite rounded leaves with fine hairs and a visible vein network; wide-angled twigs and red or sometimes white berries.","sources":[{"label":"New Zealand Plant Conservation Network","url":"https://www.nzpcn.org.nz/flora/species/coprosma-rotundifolia/"}],"checkedOn":"2026-10-04","photoCheck":{"status":"confirmed","reason":"Species source and three distinct openly licensed images visually checked.","checkedOn":"2026-10-04"}}'::jsonb, '[{"src":"https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c3/Coprosma_rotundifolia_11.jpg/960px-Coprosma_rotundifolia_11.jpg","width":960,"height":720,"caption":"Coprosma rotundifolia rounded foliage at Harcourt Park.","author":"Rudolph89","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Coprosma_rotundifolia_11.jpg","articleUrl":"https://www.nzpcn.org.nz/flora/species/coprosma-rotundifolia/","articleLabel":"NZPCN","retrievedAt":"2026-10-04","focalPoint":"50% 50%","sourceName":"Wikimedia Commons"},{"src":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b0/Coprosma_rotundifolia_12.JPG/960px-Coprosma_rotundifolia_12.JPG","width":960,"height":720,"caption":"Coprosma rotundifolia hairy, blotched leaves.","author":"Rudolph89","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Coprosma_rotundifolia_12.JPG","articleUrl":"https://www.nzpcn.org.nz/flora/species/coprosma-rotundifolia/","articleLabel":"NZPCN","retrievedAt":"2026-10-04","focalPoint":"50% 50%","sourceName":"Wikimedia Commons"},{"src":"https://thumb.wikimedia.or