  ('coprosma-rugosa', 'Coprosma rugosa', null, null, null, 'core', false, false, false, null, false, 'SP-055', null, '{"commonName":"Needle-leaved mountain coprosma","maoriNames":[],"summary":"A hardy native shrub of grassland and forest edges, extending into subalpine areas. Birds disperse the seeds from its small berries.","lookFor":"Very reduced, narrow leaves that give the plant a needle-leaved appearance. Purple-white berries can appear in autumn.","sources":[{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Coprosma_rugosa"}],"checkedOn":"2026-10-04"}'::jsonb, '[{"src":"https://upload.wikimedia.org/wikipedia/commons/4/4c/Coprosma_rugosa_258334218.jpg","width":768,"height":1024,"caption":"Coprosma rugosa, a reference specimen photographed by Mike Dickison.","author":"Mike Dickison","license":"CC BY 4.0","licenseUrl":"https://creativecommons.org/licenses/by/4.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Coprosma_rugosa_258334218.jpg","articleUrl":"https://en.wikipedia.org/wiki/Coprosma_rugosa","retrievedAt":"2026-10-03","focalPoint":"50% 50%","sourceName":"Wikimedia Commons"},{"src":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0b/Coprosma_rugosa_11.JPG/960px-Coprosma_rugosa_11.JPG","width":960,"height":720,"caption":"Coprosma rugosa, at Otari-Wilton''s Bush, Wellington, New Zealand.","author":"Rudolph89","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Coprosma_rugosa_11.JPG","articleUrl":"https://en.wikipedia.org/wiki/Coprosma_rugosa","retrievedAt":"2026-10-03","focalPoint":"50% 50%","sourceName":"Wikimedia Commons"},{"src":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d5/Coprosma_rugosa_-_Dunedin_Botanic_Garden_-_Dunedin%2C_NZ_-_DSC03458.jpg/960px-Coprosma_rugosa_-_Dunedin_Botanic_Garden_-_Dunedin%2C_NZ_-_DSC03458.jpg","width":960,"height":1440,"caption":"Coprosma rugosa. Specimen in in Dunedin Botanic Garden - Dunedin, New Zealand."