  ('fuscospora-cliffortioides', 'Fuscospora cliffortioides', null, 'Mountain beech', 'Tawairauriki', 'core', true, false, false, null, false, 'SP-069', null, '{"commonName":"Mountain beech","maoriNames":["Tawhai rauriki"],"nameNote":"WRT records the name Tawairauriki. Wikipedia also uses the botanical name Nothofagus cliffortioides.","summary":"A native beech associated with mountain forests. It can form tall forest, but becomes much shorter and more twisted near the treeline.","lookFor":"Small, elongated leaves with pointed tips. Compare the overall tree shape too: exposed mountain trees can look very different from sheltered ones.","sources":[{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Nothofagus_cliffortioides"}],"checkedOn":"2026-10-04"}'::jsonb, '[{"src":"https://upload.wikimedia.org/wikipedia/commons/1/12/Mountain_Beech.jpg","width":600,"height":896,"caption":"Fuscospora cliffortioides trees in Tongariro National Park.","author":"Andrewgprout","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Mountain_Beech.jpg","articleUrl":"https://en.wikipedia.org/wiki/Nothofagus_cliffortioides","retrievedAt":"2026-10-03","focalPoint":"50% 50%","sourceName":"Wikimedia Commons"},{"src":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/43/Mountain-Beech-foliage.jpg/960px-Mountain-Beech-foliage.jpg","width":960,"height":1278,"caption":"Fuscospora cliffortioides foliage. Wiki labels this Nothofagus solandri var. cliffortioides.","author":"Grapeman4","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Mountain-Beech-foliage.jpg","articleUrl":"https://en.wikipedia.org/wiki/Nothofagus_cliffortioides","retrievedAt":"2026-10-03","focalPoint":"50% 50%","sourceName":"Wikimedia Commons"},{"src":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9c/Mountain-Beech-tree.jpg/960px-Mountain-Beech-tree.jpg","width":960,"height":1434,"caption":"Fuscospora cliffortioides tree in Warren Park, Queenstown. Wiki uses the older name Nothofagus solandri var. cliffortioides.","author":"Andre Chalmers","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Mountain-Beech-tree.jpg","articleUrl":"https://en.wikipedia.org/wiki/Nothofagus_cliffortioides","retrievedAt":"2026-10-03","focalPoint":"50% 50%","sourceName":"Wikimedia Commons"}]'::jsonb),
  ('fuscospora-fusca', 'Fuscospora fusca', null, 'Red beech', 'Tawhairaunui', 'core', true, false, false, null, false, 'SP-070', null, '{"commonName":"Red beech","maoriNames":["Tawhai raunui"],"nameNote":"WRT records Tawhairaunui. Wikipedia’s article uses Nothofagus fusca and notes the New Zealand name Fuscospora fusca.","summary":"A large evergreen native forest tree found in both main islands. It is associated with fertile, well-drained ground on lower hills and inland valley floors.","lookFor":"Broad oval leaves with conspicuously toothed edges, unlike the small pointed leaves of mountain beech. Mature trees can grow to around 35 metres.","sources":[{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Nothofagus_fusca"}],"checkedOn":"2026-10-04"}'::jsonb, '[{"src":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5c/Nothofagus_fusca_in_Queenstown_Gardens_%281%29.jpg/960px-Nothofagus_fusca_in_Queenstown_Gardens_%281%29.jpg","width":960,"height":640,"caption":"Fuscospora fusca (labelled Nothofagus fusca by the source) in Queenstown Gardens, Otago Region, South Island of New Zealand.","author":"Krzysztof Golik","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Nothofagus_fusca_in_Queenstown_Gardens_(1).jpg","articleUrl":"https://en.wikipedia.org/wiki/Nothofagus_fusca","retrievedAt":"2026-10-04","focalPoint":"50% 50%","sourceName":"Wikimedia Commons"},{"src":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fe/Nothofagus_fusca_in_Queenstown_Gardens_%282%29.jpg/960px-Nothofagus_fusca_in_Queenstown_Gardens_%282%29.jpg","width":960,"height":640,"caption":"Fuscospora fusca (labelled Nothofagus fusca by the source) in Queenstown Gardens, Otago Region, South Island of New Zealand.","author":"Krzysztof Golik","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Nothofagus_fusca_in_Queenstown_Gardens_(2).jpg","articleUrl":"https://en.wikipedia.org/wiki/Nothofagus_fusca","retrievedAt":"2026-10-04","focalPoint":"50% 50%","sourceName":"Wikimedia Commons"},{"src":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/08/Nothofagus_fusca_in_Fiordland_National_Park_01.jpg/960px-Nothofagus_fusca_in_Fiordland_National_Park_01.jpg","width":960,"height":1100,"caption":"Fuscospora fusca (labelled Nothofagus fusca by the source) in Fiordland National Park, South Island of New Zealand.","author":"Krzysztof Golik","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Nothofagus_fusca_in_Fiordland_National_Park_01.jpg","articleUrl":"https://en.wikipedia.org/wiki/Nothofagus_fusca","retrievedAt":"2026-10-04","focalPoint":"50% 50%","sourceName":"Wikimedia Commons"}]'::jsonb),
