  ('hoheria-sexstylosa', 'Hoheria sexstylosa', null, 'Lacebark', 'Houhere', 'core', true, false, false, null, false, 'SP-081', null, '{"commonName":"Lacebark","maoriNames":["Houhere"],"nameNote":"Houhere and lacebark are shared by other Hoheria species.","summary":"A native tree of streamside forest in central New Zealand. Its tangled juvenile growth develops into a taller tree with larger leaves.","lookFor":"Toothed, pointed adult leaves and grey bark; white flowers are followed by winged dry fruit. Juvenile leaves are smaller and rounder.","sources":[{"label":"NZPCN","url":"https://www.nzpcn.org.nz/flora/species/hoheria-sexstylosa/"}],"checkedOn":"2026-10-04","photoCheck":{"status":"confirmed","reason":"Identity and profile checked; three licensed source images actually viewed.","checkedOn":"2026-10-04"}}'::jsonb, '[{"src":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/58/Hoheria_sexstylosa_11.JPG/960px-Hoheria_sexstylosa_11.JPG","width":960,"height":720,"caption":"Hoheria sexstylosa, long-leaved lacebark, on Wright''s Hill, Karori, Wellington.","author":"Rudolph89","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Hoheria_sexstylosa_11.JPG","articleUrl":"https://en.wikipedia.org/wiki/Hoheria_sexstylosa","retrievedAt":"2026-10-04","focalPoint":"50% 50%","sourceName":"Wikimedia Commons"},{"src":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/24/Hoheria_sexstylosa_kz01.jpg/960px-Hoheria_sexstylosa_kz01.jpg","width":960,"height":1440,"caption":"Hoheria sexstylosa in Dunedin Botanic Garden","author":"Krzysztof Ziarnek, Kenraiz","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Hoheria_sexstylosa_kz01.jpg","articleUrl":"https://en.wikipedia.org/wiki/Hoheria_sexstylosa","retrievedAt":"2026-10-04","focalPoint":"50% 50%","sourceName":"Wikimedia Commons"},{"src":"https://upload.wikimedia.org/wikipedia/commons/5/53/Hoheria-sexstylosa-leaves.jpg","width":659,"height":914,"caption":"Closeup of long-leaved lacebark leaves (hoheria sexstylosa)","author":"Grapeman4","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Hoheria-sexstylosa-leaves.jpg","articleUrl":"https://en.wikipedia.org/wiki/Hoheria_sexstylosa","retrievedAt":"2026-10-04","focalPoint":"50% 50%","sourceName":"Wikimedia Commons"}]'::jsonb),
  ('juncus-edgariae', 'Juncus edgariae', null, null, null, 'core', false, false, false, null, false, 'SP-082', null, '{"commonName":"Edgar’s rush","maoriNames":["Wiwi"],"nameNote":"Wiwi is a shared rush name. NZPCN distinguishes this species from Juncus continuus and the Australian J. gregiflorus, with which it was formerly confused.","summary":"A widespread endemic rush forming clumps of erect wiry stems. It grows beside wetlands, in seasonally damp places and in open shrubland or pasture.","lookFor":"Smooth shining leafless stems with branching flower clusters appearing off to one side; species separation can require checking stem pith and capsules.","sources":[{"label":"New Zealand Plant Conservation Network","url":"https://www.nzpcn.org.nz/flora/species/juncus-edgariae/"}],"checkedOn":"2026-10-04","photoCheck":{"status":"confirmed","reason":"Species source and three distinct openly licensed images visually checked.","checkedOn":"2026-10-04"}}'::jsonb, '[{"src":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b0/Juncus_edgariae_kz1.jpg/960px-Juncus_edgariae_kz1.jpg","width":960,"height":1440,"caption":"Edgar’s rush clump at Auckland Botanic Gardens.","author":"Krzysztof Ziarnek, Kenraiz","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Juncus_edgariae_kz1.jpg","articleUrl":"https://www.nzpcn.org.nz/flora/species/juncus-edgariae/","articleLabel":"NZPCN","retrievedAt":"2026-10-04","focalPoint":"50% 50%","sourceName":"Wikimedia Commons"},{"src":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e9/Juncus_edgariae_kz2.jpg/960px-Juncus_edgariae_kz2.jpg","width":960,"height":1440,"caption":"Edgar’s rush branching inflorescence.","author":"Krzysztof Ziarnek, Kenraiz","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Juncus_edgariae_kz2.jpg","articleUrl":"https://www.nzpcn.org.nz/flora/species/juncus-edgariae/","articleLabel":"NZPCN","retrievedAt":"2026-10-04","focalPoint":"50% 50%","sourceName":"Wikimedia Commons"},{"src":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/1e/Juncus_edgariae_11.JPG/960px-Juncus_edgariae_11.JPG","width":960,"height":1435,"caption":"Edgar’s rush stems and mature capsules in Upper Hutt.","author":"Rudolph89","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Juncus_edgariae_11.JPG","articleUrl":"https://www.nzpcn.org.nz/flora/species/juncus-edgariae/","articleLabel":"NZPCN","retrievedAt":"2026-10-04","focalPoint":"50% 50%","sourceName":"Wikimedia Commons"}]'::jsonb),
