  ('melicytus-alpinus', 'Melicytus alpinus', null, 'Porcupine shrub', null, 'core', false, false, false, null, false, 'SP-094', null, '{"commonName":"Porcupine shrub","maoriNames":[],"summary":"A dense, rigid native shrub adapted to dry, exposed country. Its tangled branches shelter native lizards, which also eat the fruit and disperse its seeds.","lookFor":"Stout, tapering grey-speckled branches with sparse clusters of small oval leaves. Inconspicuous flowers sit beneath branches; white berries often have purple patches.","sources":[{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Melicytus_alpinus"},{"label":"NZPCN","url":"https://www.nzpcn.org.nz/flora/species/melicytus-alpinus/"}],"checkedOn":"2026-10-04"}'::jsonb, '[{"src":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/ac/Melicytus_alpinus_-_Christchurch_Botanic_Gardens_-_Christchurch%2C_NZ_-_DSC00821.jpg/960px-Melicytus_alpinus_-_Christchurch_Botanic_Gardens_-_Christchurch%2C_NZ_-_DSC00821.jpg","width":960,"height":640,"caption":"Melicytus alpinus. Specimen in Christchurch Botanic Gardens - Christchurch, New Zealand.","author":"Daderot","license":"CC0","licenseUrl":"https://creativecommons.org/publicdomain/zero/1.0/deed.en","sourceUrl":"https://commons.wikimedia.org/wiki/File:Melicytus_alpinus_-_Christchurch_Botanic_Gardens_-_Christchurch,_NZ_-_DSC00821.jpg","articleUrl":"https://en.wikipedia.org/wiki/Melicytus_alpinus","retrievedAt":"2026-10-04","focalPoint":"50% 50%","sourceName":"Wikimedia Commons"},{"src":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b2/Melicytus_alpinus_121105688.jpg/960px-Melicytus_alpinus_121105688.jpg","width":960,"height":640,"caption":"Porcupine Shrub (Melicytus alpinus).","author":"Christopher Stephens","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Melicytus_alpinus_121105688.jpg","articleUrl":"https://en.wikipedia.org/wiki/Melicytus_alpinus","retrievedAt":"2026-10-04","focalPoint":"50% 50%","sourceName":"Wikimedia Commons"},{"src":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4b/Melicytus_alpinus_57250566.jpg/960px-Melicytus_alpinus_57250566.jpg","width":960,"height":705,"caption":"Porcupine Shrub (Melicytus alpinus).","author":"johnsteel","license":"CC BY 4.0","licenseUrl":"https://creativecommons.org/licenses/by/4.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Melicytus_alpinus_57250566.jpg","articleUrl":"https://en.wikipedia.org/wiki/Melicytus_alpinus","retrievedAt":"2026-10-04","focalPoint":"50% 50%","sourceName":"Wikimedia Commons"}]'::jsonb),
  ('melicytus-ramiflorus', 'Melicytus ramiflorus', null, null, null, 'core', true, false, false, null, false, 'SP-095', null, '{"commonName":"Whitey wood","maoriNames":["Māhoe","Hinahina"],"nameNote":"The NZPCN factsheet uses Melicytus ramiflorus subsp. ramiflorus for the New Zealand taxon and discusses the treatment of former Pacific subspecies. The WRT species-level name is retained.","summary":"A common native small tree in coastal, lowland and lower mountain forests. Its pale bark and toothed leaves are useful recognition features.","lookFor":"Light green tapered leaves with toothed edges; tiny flowers cluster along twigs and berries ripen purple.","sources":[{"label":"New Zealand Plant Conservation Network","url":"https://www.nzpcn.org.nz/flora/species/melicytus-ramiflorus-subsp-ramiflorus/"}],"checkedOn":"2026-10-04","photoCheck":{"status":"confirmed","reason":"Species source and three distinct openly licensed images visually checked.","checkedOn":"2026-10-04"}}'::jsonb, '[{"src":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/71/Mahoe-foliage.jpg/960px-Mahoe-foliage.jpg","width":960,"height":720,"caption":"Māhoe tapered, toothed foliage.","author":"Kahuroa","license":"Public domain","licenseUrl":"https://commons.wikimedia.org/wiki/Commons:Public_domain","sourceUrl":"https://commons.wikimedia.org/wiki/File:Mahoe-foliage.jpg","articleUrl":"https://www.nzpcn.org.nz/flora/species/melicytus-ramiflorus-subsp-ramiflorus/","articleLabel":"NZPCN","retrievedAt":"2026-10-04","focalPoint":"50% 50%","sourceName":"Wikimedia Commons"},{"src":"https://upload.wikimedia.org/wikipedia/commons/8/80/Melicytus_ramiflorus_-_whiteywood_flowers.jpg","width":960,"height":957,"caption":"Māhoe small flowers along a twig.","author":"Dracophyllum","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Melicytus_ramiflorus_-_whiteywood_flowers.jpg","articleUrl":"https://www.nzpcn.org.nz/flora/specie