  ('myrsine-australis', 'Myrsine australis', null, 'Red matipo', 'Mapau', 'core', true, false, false, null, false, 'SP-104', null, '{"commonName":"Red matipo","maoriNames":["Māpou","Tīpau","Mataira"],"summary":"A native shrub or small tree with a compact crown. It occurs across New Zealand in scrub and forest margins and often establishes during natural regeneration.","lookFor":"Reddish young stems and leaf stalks, with pale yellow-green, leathery leaves that usually have wavy edges. Small translucent dots may be visible in the leaves.","sources":[{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Myrsine_australis"}],"checkedOn":"2026-10-04"}'::jsonb, '[{"src":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ec/Myrsine_australis_in_Auckland_Botanic_Gardens_01.jpg/960px-Myrsine_australis_in_Auckland_Botanic_Gardens_01.jpg","width":960,"height":1440,"caption":"Myrsine australis in Auckland Botanic Gardens, Manurewa, South Auckland, New Zealand.","author":"Krzysztof Golik","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Myrsine_australis_in_Auckland_Botanic_Gardens_01.jpg","articleUrl":"https://en.wikipedia.org/wiki/Myrsine_australis","retrievedAt":"2026-10-04","focalPoint":"50% 50%","sourceName":"Wikimedia Commons"},{"src":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/95/Myrsine_australis_in_Auckland_Botanic_Gardens_02.jpg/960px-Myrsine_australis_in_Auckland_Botanic_Gardens_02.jpg","width":960,"height":640,"caption":"Myrsine australis in Auckland Botanic Gardens, Manurewa, South Auckland, New Zealand.","author":"Krzysztof Golik","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Myrsine_australis_in_Auckland_Botanic_Gardens_02.jpg","articleUrl":"https://en.wikipedia.org/wiki/Myrsine_australis","retrievedAt":"2026-10-04","focalPoint":"50% 50%","sourceName":"Wikimedia Commons"},{"src":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6f/Myrsine_australis_11.JPG/960px-Myrsine_australis_11.JPG","width":960,"height":720,"caption":"Myrsine australis, red matipo, mapou, foliage of a native tree of New Zealand.","author":"Rudolph89","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Myrsine_australis_11.JPG","articleUrl":"https://en.wikipedia.org/wiki/Myrsine_australis","retrievedAt":"2026-10-04","focalPoint":"50% 50%","sourceName":"Wikimedia Commons"}]'::jsonb),
  ('myrsine-divaricata', 'Myrsine divaricata', null, 'Weeping matipo', 'Mapou', 'core', false, false, false, null, false, 'SP-105', null, '{"commonName":"Weeping matipo","maoriNames":["Māpou"],"nameNote":"The references call this plant weeping māpou. Māpou is also used for other Myrsine species; the botanical name distinguishes this one.","summary":"A native shrub or small tree with stiff, interlacing branches that curve downwards. It occurs in forest, scrub and forest margins from lowland to mountain areas.","lookFor":"Small, leathery, often heart-shaped leaves with tiny dots and sometimes a dark blotch near their base. The fine branchlets droop; ripe berries are usually purple.","sources":[{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Myrsine_divaricata"},{"label":"NZPCN","url":"https://www.nzpcn.org.nz/flora/species/myrsine-divaricata/"}],"checkedOn":"2026-10-04"}'::jsonb, '[{"src":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6e/Myrsine_divaricata_01.jpg/960px-Myrsine_divaricata_01.jpg","width":960,"height":640,"caption":"Myrsine divaricata in Whakapapa, Waikato (New Zealand).","author":"Krzysztof Ziarnek, Kenraiz","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Myrsine_divaricata_01.jpg","articleUrl":"https://en.wikipedia.org/wiki/Myrsine_divaricata","retrievedAt":"2026-10-04","focalPoint":"50% 50%","sourceName":"Wikimedia Commons"},{"src":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fc/Myrsine_divaricata_02.jpg/960px-Myrsine_divaricata_02.jpg","width":960,"height":640,"caption":"Myrsine divaricata in Whakapapa, Waikato (New Zealand).","author":"Krzysztof Ziarnek, Kenraiz","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Myrsine_divaricata_02.jpg","articleUrl":"https://en.wikipedia.org/wiki/Myrsine_divaricata","retrievedAt":"2026-10-04","focalPoint":"50% 50%","sourceName":"Wikimedia Commons"},{"src":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/24/Myrsine_divaricata_03.jpg/960px-Myrsine_divaricata_03.jpg","width":960,"height":1440,"caption":"Myrsine divaricata in Whakapapa, Waikato (New Zealand).","author":"Krzysztof Ziarnek, Kenraiz","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Myrsine_divaricata_03.jpg","articleUrl":"https://en.wikipedia.org/wiki/Myrsine_divaricata","retrievedAt":"2026-10-04","focalPoint":"50% 50%","sourceName":"Wikimedia Commons"}]'::jsonb),
