  ('olearia-arborescens', 'Olearia arborescens', null, 'Common tree daisy', null, 'core', false, false, false, null, false, 'SP-108', null, '{"commonName":"Common tree daisy","maoriNames":[],"nameNote":"NZPCN now accepts Shawia arborescens and lists Olearia arborescens as a synonym. WRT’s database name and species ID remain separate from that nomenclatural update.","summary":"A bushy endemic shrub or small tree of forest and scrub from lowland to mountain environments.","lookFor":"Glossy leathery leaves have pale undersides and a few teeth; clusters of white daisy flowers later produce fluffy seeds.","sources":[{"label":"New Zealand Plant Conservation Network","url":"https://www.nzpcn.org.nz/flora/species/shawia-arborescens/"}],"checkedOn":"2026-10-04","photoCheck":{"status":"confirmed","reason":"Species-specific sources and three distinct licensed files were checked; selected hosted photos were visually inspected in the browser.","checkedOn":"2026-10-04"}}'::jsonb, '[{"src":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/bb/Olearia_arborescens_kz01.jpg/960px-Olearia_arborescens_kz01.jpg","width":960,"height":640,"caption":"Olearia arborescens leafy branch in Whakapapa; NZPCN now uses Shawia arborescens.","author":"Krzysztof Ziarnek, Kenraiz","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Olearia_arborescens_kz01.jpg","articleUrl":"https://www.nzpcn.org.nz/flora/species/shawia-arborescens/","articleLabel":"NZPCN","retrievedAt":"2026-10-04","focalPoint":"50% 50%","sourceName":"Wikimedia Commons"},{"src":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/67/Olearia_arborescens_in_Tongariro_National_Park_01.jpg/960px-Olearia_arborescens_in_Tongariro_National_Park_01.jpg","width":960,"height":773,"caption":"Olearia arborescens in Tongariro National Park; NZPCN now uses Shawia arborescens.","author":"Krzysztof Golik","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Olearia_arborescens_in_Tongariro_National_Park_01.jpg","articleUrl":"https://www.nzpcn.org.nz/flora/species/shawia-arborescens/","articleLabel":"NZPCN","retrievedAt":"2026-10-04","focalPoint":"50% 50%","sourceName":"Wikimedia Commons"},{"src":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d5/Olearia_arborescens_kz03.jpg/960px-Olearia_arborescens_kz03.jpg","width":960,"height":1441,"caption":"Olearia arborescens leaves and developing flower heads in Whakapapa; NZPCN now uses Shawia arborescens.","author":"Krzysztof Ziarnek, Kenraiz","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Olearia_arborescens_kz03.jpg","articleUrl":"https://www.nzpcn.org.nz/flora/species/shawia-arborescens/","articleLabel":"NZPCN","retrievedAt":"2026-10-04","focalPoint":"50% 50%","sourceName":"Wikimedia Commons"}]'::jsonb),
  ('olearia-avicenniifolia', 'Olearia avicenniifolia', null, 'Mountain akeake', 'Akeake', 'core', true, false, false, null, false, 'SP-109', null, '{"commonName":"Mountain akeake","maoriNames":["Akeake"],"nameNote":"NZPCN and Wikipedia now use Shawia avicenniifolia; the database retains Olearia avicenniifolia. Akeake is a shared Māori name used for several trees, including Dodonaea viscosa.","summary":"A bushy New Zealand shrub or small tree with leathery leaves and clusters of white daisy-like flowers. Pale hairs on the leaf undersides and young shoots give it a distinctive appearance.","lookFor":"Narrow, pointed, dark-green leaves with white, felted undersides. The white flower clusters develop into fluffy seeds.","sources":[{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Olearia_avicenniifolia"},{"label":"New Zealand Plant Conservation Network","url":"https://www.nzpcn.org.nz/flora/species/shawia-avicenniifolia/"},{"label":"NZOR — Akeake","url":"https://www.nzor.org.nz/names/47ccb479-4148-4a6c-82c5-32c50bea750f"}],"checkedOn":"2026-10-04"}'::jsonb, '[{"src":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a4/Olearia_avicenniifolia_kz01.jpg/960px-Olearia_avicenniifolia_kz01.jpg","width":960,"height":640,"caption":"Olearia avicenniifolia in Aoraki Mt Cook Village, Canterbury (New Zealand).","author":"Krzysztof Ziarnek, Kenraiz","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Olearia_avicenniifolia_kz01.jpg","articleUrl":"https://en.wikipedia.org/wiki/Olearia_avicenniifolia","retrievedAt":"2026-10-04","focalPoint":"50% 50%","sourceName":"Wikimedia Commons"},{"src":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e6/Olearia_avicenniifolia_kz02.jpg/960px-Olearia_avicenniifolia_kz02.jpg","width":960,"height":640,"caption":"Olearia avicenniifolia in Aoraki Mt Cook Village, Canterbury (New Zealand).","author":"Krzysztof Ziarnek, Kenraiz","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Olearia_avicenniifolia_kz02.jpg","articleUrl":"https://en.wikipedia.org/wiki/Olearia_avicenniifolia","retrievedAt":"2026-10-04","focalPoint":"50% 50%","sourceName":"Wikimedia Commons"},{"src":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f1/Olearia_avicenniifolia_kz03.jpg/960px-Olearia_avicenniifolia_kz03.jpg","width":960,"height":1440,"caption":"Olearia avicenniifolia in Aoraki Mt Cook Village, Canterbury (New Zealand).","author":"Krzysztof Ziarnek, Kenraiz","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Olearia_avicenniifolia_kz03.jpg","articleUrl":"https://en.wikipedia.org/wiki/Olearia_avicenniifolia","retrievedAt":"2026-10-04","focalPoint":"50% 50%","sourceName":"Wikimedia Commons"}]'::jsonb),
  ('olearia-bullata', 'Olearia bullata', null, null, null, 'core', false, false, false, null, false, 'SP-110', null, '{"commonName":"Tree daisy","maoriNames":[],"nameNote":"Tree daisy is a group name used for several species. NZPCN now lists this plant as Shawia bullata; WRT’s recorded name is retained here.","summary":"A bushy native shrub with many interlacing reddish twigs. It is associated with wet places in the eastern South Island and can reach around three metres.","lookFor":"Tiny, wrinkled leaves with rolled edges and white undersides. The brownish-green foliage and dense tangle of twigs give the bush a greyish appearance.","sources":[{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Olearia_bullata"},{"label":"NZPCN","url":"https://www.nzpcn.org.nz/flora/species/shawia-bullata/"},{"label":"Ashburton District Council · common name","url":"https://www.ashburtondc.govt.nz/community-facilities/ashburton-district/native-plants-in-our-district"}],"checkedOn":"2026-10-04"}'::jsonb, '[{"src":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/37/Olearia_bullata_in_Dunedin_Botanic_Garden_01.jpg/960px-Olearia_bullata_in_Dunedin_Botanic_Garden_01.jpg","width":960,"height":709,"caption":"Olearia bullata in Dunedin Botanic Garden, Dunedin, New Zealand.","author":"Krzysztof Golik","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Olearia_bullata_in_Dunedin_Botanic_Garden_01.jpg","articleUrl":"https://en.wikipedia.org/wiki/Olearia_bullata","retrievedAt":"2026-10-04","focalPoint":"50% 50%","sourceName":"Wikimedia Commons"},{"src":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/be/Olearia_bullata_in_Dunedin_Botanic_Garden_02.jpg/960px-Olearia_bullata_in_Dunedin_Botanic_Garden_02.jpg","width":960,"height":640,"caption":"Olearia bullata in Dunedin Botanic Garden, Dunedin, New Zealand.","author":"Krzysztof Golik","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Olearia_bullata_in_Dunedin_Botanic_Garden_02.jpg","articleUrl":"https://en.wikipedia.org/wiki/Olearia_bullata","retrievedAt":"2026-10-04","focalPoint":"50% 50%","sourceName":"Wikimedia Commons"},{"src":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/97/Olearia-bullata.jpg/960px-Olearia-bullata.jpg","width":960,"height":721,"caption":"Olearia bullata bush focusing on the leaves.\nMatakauri Park, Queenstown.","author":"Andre Chalmers","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Olearia-bullata.jpg","articleUrl":"https://en.wikipedia.org/wiki/Olearia_bullata","retrievedAt":"2026-10-04","focalPoint":"50% 50%","sourceName":"Wikimedia Commons"}]'::jsonb),
