  ('olearia-fimbriata', 'Olearia fimbriata', null, null, null, 'core', true, true, true, null, false, 'SP-112', null, '{"commonName":"Small-leaved tree daisy","maoriNames":[],"summary":"A tree daisy of the eastern South Island, including Otago and northern Southland. It grows in grey scrub and open rocky country and supports specialist native moths.","lookFor":"Opposite pairs of small, dull grey-green leaves, hairy underneath. Fine outer branchlets hang down, and clusters of cream flowers appear in summer.","sources":[{"label":"DOC species factsheet · PDF","url":"https://www.nzpcn.org.nz/site/assets/files/0/13/485/olearia_fimbriata.pdf"}],"checkedOn":"2026-10-04"}'::jsonb, '[{"src":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/1b/Olearia_fimbriata_in_Dunedin_Botanic_Garden_01.jpg/960px-Olearia_fimbriata_in_Dunedin_Botanic_Garden_01.jpg","width":960,"height":640,"caption":"Olearia fimbriata at Dunedin Botanic Garden.","author":"Krzysztof Golik","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Olearia_fimbriata_in_Dunedin_Botanic_Garden_01.jpg","articleUrl":"https://en.wikipedia.org/wiki/Olearia_fimbriata","retrievedAt":"2026-10-03","focalPoint":"50% 50%","sourceName":"Wikimedia Commons"},{"src":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3b/Olearia_fimbriata_in_Auckland_Botanic_Gardens_01.jpg/960px-Olearia_fimbriata_in_Auckland_Botanic_Gardens_01.jpg","width":960,"height":640,"caption":"Olearia fimbriata in Auckland Botanic Gardens, Manurewa, South Auckland, New Zealand","author":"Krzysztof Golik","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Olearia_fimbriata_in_Auckland_Botanic_Gardens_01.jpg","articleUrl":"https://en.wikipedia.org/wiki/Olearia_fimbriata","retrievedAt":"2026-10-03","focalPoint":"50% 50%","sourceName":"Wikimedia Commons"},{"src":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5e/Olearia_fimbriata_in_Dunedin_Botanic_Garden_02.jpg/960px-Olearia_fimbriata_in_Dunedin_Botanic_Garden_02.jpg","width":960,"height":640,"caption":"Olearia fimbriata in Dunedin Botanic Garden, Dunedin, New Zealand","author":"Krzysztof Golik","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Olearia_fimbriata_in_Dunedin_Botanic_Garden_02.jpg","articleUrl":"https://en.wikipedia.org/wiki/Olearia_fimbriata","retrievedAt":"2026-10-03","focalPoint":"50% 50%","sourceName":"Wikimedia Commons"}]'::jsonb),
  ('olearia-fragrantissima', 'Olearia fragrantissima', null, 'Fragrant tree daisy', null, 'core', true, true, true, null, false, 'SP-113', null, '{"commonName":"Fragrant tree daisy","maoriNames":[],"nameNote":"NZPCN now uses Shawia fragrantissima. The profile keeps Olearia fragrantissima to match WRT’s historical species ID.","summary":"A native shrub or small tree of the eastern and southern South Island. Its small flower clusters have a strong, sweet fragrance, particularly at night, and it can lose some or all of its leaves seasonally.","lookFor":"Reddish-brown, zig-zagging twigs; small leaves that are hairy underneath; and tight clusters of pale yellow flowers. Older bark peels in long strips.","sources":[{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Olearia_fragrantissima"},{"label":"New Zealand Plant Conservation Network","url":"https://www.nzpcn.org.nz/flora/species/shawia-fragrantissima/"}],"checkedOn":"2026-10-04"}'::jsonb, '[{"src":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/1c/Olearia_fragrantissima_kz01.jpg/960px-Olearia_fragrantissima_kz01.jpg","width":960,"height":1440,"caption":"Olearia fragrantissima in Dunedin Botanic Garden.","author":"Krzysztof Ziarnek, Kenraiz","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Olearia_fragrantissima_kz01.jpg","articleUrl":"https://en.wikipedia.org/wiki/Olearia_fragrantissima","retrievedAt":"2026-10-04","focalPoint":"50% 50%","sourceName":"Wikimedia Commons"},{"src":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8d/Olearia_fragrantissima_kz02.jpg/960px-Olearia_fragrantissima_kz02.jpg","width":960,"height":640,"caption":"Olearia fragrantissima in Dunedin Botanic Garden.","author":"Krzysztof Ziarnek, Kenraiz","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Olearia_fragrantissima_kz02.jpg","articleUrl":"https://en.wikipedia.org/wiki/Olearia_fragrantissima","retrievedAt":"2026-10-04","focalPoint":"50% 50%","sourceName":"Wikimedia Commons"},{"src":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/97/Olearia_fragrantissima_kz03.jpg/960px-Olearia_fragrantissima_kz03.jpg","width":960,"height":640,"caption":"Olearia fragrantissima in Dunedin Botanic Garden.","author":"Krzysztof Ziarnek, Kenraiz","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Olearia_fragrantissima_kz03.jpg","articleUrl":"https://en.wikipedia.org/wiki/Olearia_fragrantissima","retrievedAt":"2026-10-04","focalPoint":"50% 50%","sourceName":"Wikimedia Commons"}]'::jsonb),
  ('olearia-hectorii', 'Olearia hectorii', null, 'Hectors tree daisy', null, 'core', true, true, true, null, false, 'SP-114', null, '{"commonName":"Hector’s tree daisy","maoriNames":[],"summary":"A deciduous native tree daisy with reddish young stems and furrowed bark. It supports many native moth species and needs open ground for seedlings to establish.","lookFor":"Clusters of grey-green leaves arranged opposite one another, with silvery undersides. Its small flower heads contain pale-yellow florets.","sources":[{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Olearia_hectorii"}],"checkedOn":"2026-10-04"}'::jsonb, '[{"src":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/18/Olearia_hectorii%2C_mature_tree.jpg/960px-Olearia_hectorii%2C_mature_tree.jpg","width":960,"height":626,"caption":"Mature Olearia hectorii photographed by John Barkla, Department of Conservation.","author":"John Barkla, Department of Conservation (New Zealand)","license":"CC BY 4.0","licenseUrl":"https://creativecommons.org/licenses/by/4.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Olearia_hectorii,_mature_tree.jpg","articleUrl":"https://en.wikipedia.org/wiki/Olearia_hectorii","retrievedAt":"2026-10-03","focalPoint":"50% 50%","sourceName":"Wikimedia Commons"},{"src":"https://inaturalist-open-data.s3.amazonaws.com/photos/96583759/large.jpeg","width":1024,"height":768,"caption":"Olearia hectorii flower buds and opening flowers, photographed by John Barkla.","author":"John Barkla","license":"CC BY 4.0","licenseUrl":"https://creativecommons.org/licenses/by/4.0/","sourceUrl":"https://www.inaturalist.org/photos/96583759","articleUrl":"https://en.wikipedia.org/wiki/Olearia_hectorii","retrievedAt":"2026-10-03","focalPoint":"50% 50%","sourceName":"iNaturalist","observationUrl":"https://www.inaturalist.org/observations/60402502"},{"src":"https://inaturalist-open-data.s3.amazonaws.com/photos/96583766/large.jpeg","width":768,"height":1024,"caption":"Olearia hectorii trunk and bark 