  ('phormium-tenax', 'Phormium tenax', null, 'Swamp flax', 'Harakeke', 'core', false, false, false, null, false, 'SP-127', null, '{"commonName":"New Zealand flax","maoriNames":["Harakeke"],"summary":"An evergreen plant that grows in large clumps. Harakeke is an important fibre plant, with a long history of use in Māori weaving.","lookFor":"Long, upright strap-like leaves emerging from the base. Tall flowering stalks rise above the foliage with red or yellow flowers.","sources":[{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Phormium_tenax"}],"checkedOn":"2026-10-04"}'::jsonb, '[{"src":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7b/Phormium_tenax_Piha02.jpg/960px-Phormium_tenax_Piha02.jpg","width":960,"height":1424,"caption":"Phormium tenax in flower at Piha, Auckland.","author":"Kahuroa","license":"Public domain","licenseUrl":"https://commons.wikimedia.org/wiki/Commons:Public_domain","sourceUrl":"https://commons.wikimedia.org/wiki/File:Phormium_tenax_Piha02.jpg","articleUrl":"https://en.wikipedia.org/wiki/Phormium_tenax","retrievedAt":"2026-10-03","focalPoint":"50% 50%","sourceName":"Wikimedia Commons"},{"src":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2d/Leaf_tip%2C_New_Zealand_flax_%28Phormium_tenax%29%2C_backlit_by_evening_sun.jpg/960px-Leaf_tip%2C_New_Zealand_flax_%28Phormium_tenax%29%2C_backlit_by_evening_sun.jpg","width":960,"height":1459,"caption":"Tip of leaf of New Zealand flax (Phormium tenax), backlit by evening sun. Photo taken above Maori Bay, near Auckland, New Zealand.","author":"Avenue","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Leaf_tip,_New_Zealand_flax_(Phormium_tenax),_backlit_by_evening_sun.jpg","articleUrl":"https://en.wikipedia.org/wiki/Phormium_tenax","retrievedAt":"2026-10-03","focalPoint":"50% 50%","sourceName":"Wikimedia Commons"},{"src":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/15/New_Zealand_flax_in_flower_close-up.jpg/960px-New_Zealand_flax_in_flower_close-up.jpg","width":960,"height":640,"caption":"Phormium tenax. New Zealand flax in flower close-up","author":"Pseudopanax at English Wikipedia","license":"Public domain","licenseUrl":"https://commons.wikimedia.org/wiki/Commons:Public_domain","sourceUrl":"https://commons.wikimedia.org/wiki/File:New_Zealand_flax_in_flower_close-up.jpg","articleUrl":"https://en.wikipedia.org/wiki/Phormium_tenax","retrievedAt":"2026-10-03","focalPoint":"50% 50%","sourceName":"Wikimedia Commons"}]'::jsonb),
  ('phyllocladus-alpinus', 'Phyllocladus alpinus', null, 'Mountain celery pine', 'Toatoa', 'core', true, false, false, null, false, 'SP-128', null, '{"commonName":"Mountain celery pine","maoriNames":["Toatoa"],"nameNote":"NZPCN lists mountain toatoa; toatoa is shared with other celery pines. Its factsheet excludes the distinct unnamed yellow-foliaged P. aff. alpinus entity.","summary":"An endemic conifer shrub or small tree chiefly found in subalpine scrub and low alpine habitats, also occurring on low-elevation frost flats.","lookFor":"Flattened grey-green leaf-like stems, called phylloclades, with lobed or toothed margins; seeds develop on red fleshy scales.","sources":[{"label":"New Zealand Plant Conservation Network","url":"https://www.nzpcn.org.nz/flora/species/phyllocladus-alpinus/"}],"checkedOn":"2026-10-04","photoCheck":{"status":"confirmed","reason":"Species source and three distinct openly licensed images visually checked.","checkedOn":"2026-10-04"}}'::jsonb, '[{"src":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/02/Mountain_Toatoa_%28Phyllocladus_alpinus%29.jpg/960px-Mountain_Toatoa_%28Phyllocladus_alpinus%29.jpg","width":960,"height":1280,"caption":"Mountain celery pine with red cone structures at Tongariro.","author":"Matt Berger","license":"CC BY 4.0","licenseUrl":"https://creativecommons.org/licenses/by/4.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Mountain_Toatoa_(Phyllocladus_alpinus).jpg","articleUrl":"https://www.nzpcn.org.nz/flora/species/phyllocladus-alpinus/","articleLabel":"NZPCN","retrievedAt":"2026-10-04","focalPoint":"50% 50%","sourceName":"Wikimedia Commons"},{"src":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b2/Phyllocladus_alpinus_foliage.jpg/960px-Phyllocladus_alpinus_foliage.jpg","width":960,"height":1280,"caption":"Mountain celery pine phylloclades at Arthur’s Pass.","author":"Matt Berger","license":"CC BY 4.0","licenseUrl":"https://creativecommons.org/licenses/by/4.0","sourceUrl":"https://commons.wikim