  ('pseudopanax-crassifolius', 'Pseudopanax crassifolius', null, 'Lancewood', 'Horoeka', 'core', true, false, false, null, false, 'SP-146', null, '{"commonName":"Lancewood","maoriNames":["Horoeka"],"nameNote":"Horoeka is also used for toothed lancewood, Pseudopanax ferox. Their profiles and planting records remain separate.","summary":"A native tree with dramatically different juvenile and adult forms. Young plants carry long, downward-pointing leaves on one slender stem; mature trees branch and develop a rounded crown.","lookFor":"Long, stiff juvenile leaves with a prominent midrib and toothed edges. Adult leaves are much shorter and broader. Pseudopanax ferox has more strongly jagged juvenile leaves.","sources":[{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Pseudopanax_crassifolius"}],"checkedOn":"2026-10-04"}'::jsonb, '[{"src":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/70/Pseudopanax_crassifolius_in_Aoraki_Mount_Cook_NP_01.jpg/960px-Pseudopanax_crassifolius_in_Aoraki_Mount_Cook_NP_01.jpg","width":960,"height":1440,"caption":"Pseudopanax crassifolius at Governor''s Bush Walk in Aoraki/Mount Cook National Park, Canterbury Region, South Island of New Zealand.","author":"Krzysztof Golik","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Pseudopanax_crassifolius_in_Aoraki_Mount_Cook_NP_01.jpg","articleUrl":"https://en.wikipedia.org/wiki/Pseudopanax_crassifolius","retrievedAt":"2026-10-04","focalPoint":"50% 50%","sourceName":"Wikimedia Commons"},{"src":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7b/Pseudopanax_crassifolius_in_Aoraki_Mount_Cook_NP_02.jpg/960px-Pseudopanax_crassifolius_in_Aoraki_Mount_Cook_NP_02.jpg","width":960,"height":640,"caption":"Pseudopanax crassifolius at Governor''s Bush Walk in Aoraki/Mount Cook National Park, Canterbury Region, South Island of New Zealand.","author":"Krzysztof Golik","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Pseudopanax_crassifolius_in_Aoraki_Mount_Cook_NP_02.jpg","articleUrl":"https://en.wikipedia.org/wiki/Pseudopanax_crassifolius","retrievedAt":"2026-10-04","focalPoint":"50% 50%","sourceName":"Wikimedia Commons"},{"src":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d8/Lancewood_leaves_%28mature%29.jpg/960px-Lancewood_leaves_%28mature%29.jpg","width":960,"height":1280,"caption":"Leaves of a mature New Zealand Lancewood (Pseudopanax crassifolius, growing near the Old Arts Building of the University of Auckland.","author":"Avenue","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0/","sourceUrl":"https://commons.wikimedia.org/wiki/File:Lancewood_leaves_(mature).jpg","articleUrl":"https://en.wikipedia.org/wiki/Pseudopanax_crassifolius","retrievedAt":"2026-10-04","focalPoint":"50% 50%","sourceName":"Wikimedia Commons"}]'::jsonb),
  ('pseudopanax-ferox', 'Pseudopanax ferox', null, 'Fierce lancewood', null, 'core', true, true, false, null, false, 'SP-147', null, '{"commonName":"Toothed lancewood","maoriNames":["Horoeka"],"nameNote":"Also called fierce lancewood. Horoeka is shared with Pseudopanax crassifolius; the two species remain separate in the database.","summary":"A small New Zealand tree whose appearance changes markedly as it matures. Young plants have a single stem and striking, jagged leaves; adults develop a branching crown and shorter leaves.","lookFor":"Stiff, narrow juvenile leaves hanging downward, with large, irregular teeth along the edges. Compare these with the less strongly toothed leaves of Pseudopanax crassifolius.","sources":[{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Pseudopanax_ferox"}],"checkedOn":"2026-10-04"}'::jsonb, '[{"src":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3f/Pseudopanax_ferox_-_grove_at_%C5%8Ctari-Wilton%27s_Bush.jpg/960px-Pseudopanax_ferox_-_grove_at_%C5%8Ctari-Wilton%27s_Bush.jpg","width":960,"height":720,"caption":"Pseudopanax ferox - grove at Ōtari-Wilton''s Bush.","author":"Marshelec","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Pseudopanax_ferox_-_grove_at_%C5%8Ctari-Wilton%27s_Bush.jpg","articleUrl":"https://en.wikipedia.org/wiki/Pseudopanax_ferox","retrievedAt":"2026-10-04","focalPoint":"50% 50%","sourceName":"Wikimedia Commons"},{"src":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/20/Pseudopanax_ferox_%28new_juvenile_growth_close-up%29.jpg/960px-Pseudopanax_ferox_%28new_juvenile_growth_close-up%29.jpg","width":960,"height":720,"caption":"Pseudopanax ferox. Close-up of new spring growth at tip of a juvenile toothed lancewood. Photo taken in Pukerua Bay, New Zealand, in spring. The emerging leaves in the picture are 2-4cm long.","author":"Pseudopanax at en.wikipedia","license":"Public domain","licenseUrl":"https://commons.wikimedia.org/wiki/File:Pseudopanax_ferox_(new_juvenile_growth_close-up).jpg#Licensing","sourceUrl":"https://commons.wikimedia.org/wiki/File:Pseudopanax_ferox_(new_juvenile_growth_close-up).jpg","articleUrl":"https://en.wikipedia.org/wiki/Pseudopanax_ferox","retrievedAt":"2026-10-04","focalPoint":"50% 50%","sourceName":"Wikimedia Commons"},{"src":"https://thumb.wikimedia.org/wikipedia/commons/b/b6/Lancewood_%28Pseudopanax_ferox%29_-_adolescent.jpg","width":960,"height":2620,"caption":"A lancewood (Pseudopanax ferox) that is changing from the juvenile to the mature form. Note the different leaf shapes low and high on the tree. Growing near the Old Arts Building of the University of Auckland, New Zealand.","author":"Avenue","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0/","sourceUrl":"https://commons.wikimedia.org/wiki/File:Lancewood_(Pseudopanax_ferox)_-_adolescent.jpg","articleUrl":"https://en.wikipedia.org/wiki/Pseudopanax_ferox","retrievedAt":"2026-10-04","focalPoint":"50% 50%","sourceName":"Wikimedia Commons"}]'::jsonb),
  ('pseudowintera-colorata', 'Pseudowintera colorata', null, 'Pepper tree', 'Horopito', 'core', true, false, false, null, false, 'SP-148', null, '{"commonName":"Mountain horopito","maoriNames":["Horopito"],"nameNote":"Horopito is shared with other Pseudowintera species; NZPCN calls this one red or mountain horopito.","summary":"An endemic shrub of forest edges and scrub through the North, South and Stewart islands. Its leaf colouring becomes especially conspicuous in exposed places.","lookFor":"Matte green to yellow-green oval leaves often blotched red, with pale whitish undersides. Dark branchlets bear small yellow-green flowers and dark red or black berries.","sources":[{"label":"NZPCN","url":"https://www.nzpcn.org.nz/flora/species/pseudowintera-colorata/"}],"checkedOn":"2026-10-04","photoCheck":{"status":"confirmed","reason":"Identity and profile checked; three licensed source images actually viewed.","checkedOn":"2026-10-04"}}'::jsonb, '[{"src":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6b/Christchurch_Botanic_Gardens%2C_New_Zealand_section%2C_pseudowintera_colorata_2016-02-04.jpg/960px-Christchurch_Botanic_Gardens%2C_New_Zealand_section%2C_pseudowintera_colorata_2016-02-04.jpg","width":960,"height":1440,"caption":"Pseudowintera colorata","author":"Szilas","license":"Public domain","licenseUrl":"https://commons.wikimedia.org/wiki/Commons:Public_domain","sourceUrl":"https://commons.wikimedia.org/wiki/File:Christchurch_Botanic_Gardens,_New_Zealand_section,_pseudowintera_colorata_2016-02-04.jpg","articleUrl":"https://en.wikipedia.org/wiki/Pseudowintera_colorata","retrievedAt":"2026-10-04","focalPoint":"50% 50%","sourceName":"Wikimedia Commons"},{"src":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/17/Pseudowintera_colorata_in_Mount_Aspiring_NP_02.jpg/960px-Pseudowintera_colorata_in_Mount_Aspiring_NP_02.jpg","width":960,"height":1001,"caption":"Leaf of Pseudowintera colorata in Mount Aspiring National Park, South Island of New Zealand","author":"