  ('streblus-heterophyllus', 'Streblus heterophyllus', null, 'Small leaved milk tree', 'Tūrepo', 'core', true, false, false, null, false, 'SP-153', null, '{"commonName":"Small-leaved milk tree","maoriNames":["Tūrepo"],"nameNote":"The database spelling Streblus heterophyllus is retained. NZPCN currently accepts Paratrophis microphylla and explicitly lists Streblus heterophyllus as a synonym. These source names refer to this taxon, not a merged database record.","summary":"An endemic forest tree with a marked change between its wiry, small-leaved juvenile form and broader adult foliage. Small red fruits develop along the branches.","lookFor":"Young plants have slender interlacing twigs and tiny irregularly lobed leaves. Adult leaves are small and oval with shallow teeth and visible veins; fruit is red.","sources":[{"label":"New Zealand Plant Conservation Network","url":"https://www.nzpcn.org.nz/flora/species/paratrophis-microphylla/"}],"checkedOn":"2026-10-04","photoCheck":{"status":"confirmed","reason":"Species-specific sources and three distinct licensed files were checked; selected hosted photos were visually inspected in the browser.","checkedOn":"2026-10-04"}}'::jsonb, '[{"src":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b6/Streblus_heterophyllus_12.JPG/960px-Streblus_heterophyllus_12.JPG","width":960,"height":784,"caption":"Tūrepo / small-leaved milk tree, adult form.","author":"Rudolph89","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Streblus_heterophyllus_12.JPG","articleUrl":"https://www.nzpcn.org.nz/flora/species/paratrophis-microphylla/","articleLabel":"NZPCN","retrievedAt":"2026-10-04","focalPoint":"50% 50%","sourceName":"Wikimedia Commons"},{"src":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0f/Streblus_heterophyllus_11.JPG/960px-Streblus_heterophyllus_11.JPG","width":960,"height":644,"caption":"Tūrepo seedling foliage.","author":"Rudolph89","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Streblus_heterophyllus_11.JPG","articleUrl":"https://www.nzpcn.org.nz/flora/species/paratrophis-microphylla/","articleLabel":"NZPCN","retrievedAt":"2026-10-04","focalPoint":"50% 50%","sourceName":"Wikimedia Commons"},{"src":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f1/Streblus_heterophyllus_110234300.jpg/960px-Streblus_heterophyllus_110234300.jpg","width":960,"height":1998,"caption":"Tūrepo foliage and red fruit.","author":"titine","license":"CC BY 4.0","licenseUrl":"https://creativecommons.org/licenses/by/4.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Streblus_heterophyllus_110234300.jpg","articleUrl":"https://www.nzpcn.org.nz/flora/species/paratrophis-microphylla/","articleLabel":"NZPCN","retrievedAt":"2026-10-04","focalPoint":"50% 50%","sourceName":"Wikimedia Commons"}]'::jsonb),
  ('veronica-biggarii', 'Veronica biggarii', null, null, null, 'core', false, false, false, null, false, 'SP-154', null, '{"commonName":"Biggar’s hebe","maoriNames":[],"nameNote":"NZPCN lists Hebe biggarii as a synonym and describes this range-restricted species as Naturally Uncommon. No Māori name was verified.","summary":"A small Southland alpine shrub restricted to the Eyre and Thomson mountains and Mid Dome. It grows on rocky outcrops and in open snow-tussock grassland.","lookFor":"Pairs of fleshy oval leaves often edged red; flower spikes on noticeable stalks, with bright pink young buds or developing capsules.","sources":[{"label":"New Zealand Plant Conservation Network","url":"https://www.nzpcn.org.nz/flora/species/veronica-biggarii/"}],"checkedOn":"2026-10-04","photoCheck":{"status":"partial","reason":"Only one suitable Commons photograph was found. The nine iNaturalist observations returned for taxon 738691 included this same CC BY image, five research-grade observations with CC BY-NC photos, one research-grade observation without photo licences, and two casual observations without images. Restricted or unlicensed photos excluded; no image quota forced.","summary":"Only one suitable reusable image was confirmed. Two more references are still needed.","checkedOn":"2026-10-04"}}'::jsonb, '[{"src":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5c/Veronica_biggarii_-_John_Barkla_-_1228975.jpeg/960px-Veronica_biggarii_-_John_Barkla_-_1228975.jpeg","width":960,"height":639,"caption":"Biggar’s hebe flowers and red-margined leaves in Dunedin.","author":"John Barkla","license":"CC BY 4.0","licenseUrl":"https://creativecommons.org/licenses/by/4.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Veronica_biggarii_-_John_Barkla_-_1228975.jpeg","articleUrl":"https://www.nzpcn.org.nz/flora/species/veronica-biggarii/","articleLabel":"NZPCN","retrievedAt":"2026-10-04","focalPoint":"50% 50%","sourceName":"Wikimedia Commons"}]'::jsonb),
  ('veronica-cupressoides', 'Veronica cupressoides', null, null, null, 'contested', false, true, false, 'C2', true, 'SP-155', 'C2: One species written twice in every master list (Master Plant List rows 44 and 92)? Threatened flag is on the Veronica row only.', '{"commonName":"Cypress hebe","maoriNames":[],"nameNote":"Older sources and some image files use Hebe cupressoides. This profile applies only to Veronica cupressoides and does not merge WRT’s disputed names.","summary":"An aromatic, bushy native shrub of eastern South Island grey scrub. Its fine branchlets and tiny scale leaves give it a cypress-like appearance, despite being a flowering shrub.","lookFor":"Slender blue-green branchlets with widely spaced, triangular scale leaves. Small pale pink, mauve or blue flowers occur near the shoot tips.","sources":[{"label":"New Zealand Plant Conservation Network","url":"https://www.nzpcn.org.nz/flora/species/veronica-cupressoides/"}],"checkedOn":"2026-10-04"}'::jsonb, '[{"src":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9a/Veronica_cupressoides_at_WBG.jpg/960px-Veronica_cupressoides_at_WBG.jpg","width":960,"height":720,"caption":"Veronica cupressoides at Wellington Botanic Garden.","author":"Siobhan Leachman","license":"CC0","licenseUrl":"https://creativecommons.org/publicdomain/zero/1.0/deed.en","sourceUrl":"https://commons.wikimedia.org/wiki/File:Veronica_cupressoides_at_WBG.jpg","articleUrl":"https://www.nzpcn.org.nz/flora/species/veronica-cupressoides/","retrievedAt":"2026-10-04","focalPoint":"50% 50%","sourceName":"Wikimedia Commons","articleLabel":"NZPCN species page"},{"src":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6c/Veronica_cupressoides2_at_WBG.jpg/960px-Veronica_cupressoides2_at_WBG.jpg","width":960,"height":1280,"caption":"Veronica cupressoides at Wellington Botanic Garden.","author":"Siobhan Leachman","license":"CC0","licenseUrl":"https://creativecommons.org/publicdomain/zero/1.0/deed.en","sourceUrl":"https://commons.wikimedia.org/wiki/File:Veronica_cupressoides2_at_WBG.jpg","articleUrl":"https://www.nzpcn.org.nz/flora/species/veronica-cupressoides/","retrievedAt":"2026-10-04","focalPoint":"50% 50%","sourceName":"Wikimedia Commons","articleLabel":"NZPCN species page"},{"src":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/50/Veronica_cupressoides_kz01.jpg/960px-Veronica_cupressoides_kz01.jpg","width":960,"height":1280,"caption":"Veronica cupressoides in Christchurch Botanic Gardens.","author":"Krzysztof Ziarnek, Kenraiz","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Veronica_cupressoides_kz01.jpg","articleUrl":"https://www.nzpcn.org.nz/flora/species/veronica-cupressoides/","retrievedAt":"2026-10-04","focalPoint":"50% 50%","sourceName":"Wikimedia Commons","articleLabel":"NZPCN species page"}]'::jsonb),
  ('veronica-hectorii', 'Veronica hectorii', null, null, null, 'contested', false, false, false, 'C8', true, 'SP-156', 'C8: Is the demissa variety its own line or folded into the parent?', '{"commonName":"Whipcord hebe","maoriNames":[],"nameNote":"Whipcord hebe is shared with several species. Flora of New Zealand recognises three subspecies and lists Hebe hectorii and Leonohebe hectorii as synonyms. No subspecies is assigned here, and WRT’s disputed separate demissa line remains unresolved.","summary":"An endemic compact shrub of mountain grassland and scrub in the South and Stewart islands. Its tightly pressed scale leaves make the shoots look like cords.","lookFor":"Short upright shoots sheathed in overlapping pairs of glossy green or olive scale leaves. Small white flowers crowd the branch tips.","sources":[{"label":"Flora of New Zealand","url":"https://www.nzflora.info/factsheet/Taxon/Veronica-hectorii.html"}],"checkedOn":"2026-10-04","photoCheck":{"status":"partial","reason":"Botanical references confirmed; WRT database boundary or spelling decision remains unresolved.","summary":"No subspecies has been assigned to WRT’s records. The separate demissa entry still needs a ruling.","checkedOn":"2026-10-04"}}'::jsonb, '[{"src":"https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c3/Veronica_hectorii_in_Christchurch_Botanic_Gardens_01.jpg/960px-Veronica_hectorii_in_Christchurch_Botanic_Gardens_01.jpg","width":960,"height":640,"caption":"Veronica hectorii in Christchurch Botanic Gardens in Christchurch, Canterbury Region, New Zealand","author":"Krzysztof Golik","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Veronica_hectorii_in_Christchurch_Botanic_Gardens_01.jpg","articleUrl":"https://en.wikipedia.org/wiki/Veronica_hectorii","retrievedAt":"2026-10-04","focalPoint":"50% 50%","sourceName":"Wikimedia Commons"},{"src":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/32/Veronica_hectorii_in_Christchurch_Botanic_Gardens_02.jpg/960px-Veronica_hectorii_in_Christchurch_Botanic_Gardens_02.jpg","width":960,"height":640,"caption":"Veronica hectorii in Christchurch Botanic Gardens in Christchurch, Canterbury Region, New Zealand","author":"Krzysztof Golik","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Veronica_hectorii_in_Christchurch_Botanic_Gardens_02.jpg","articleUrl":"https://en.wikipedia.org/wiki/Veronica_hectorii","retrievedAt":"2026-10-04","focalPoint":"50% 50%","sourceName":"Wikimedia Commons"},{"src":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/78/Veronica_hectorii_-_Flavien_Saboureau_-_463853303.jpeg/960px-Veronica_hectorii_-_Flavien_Saboureau_-_463853303.jpeg","width":960,"height":1280,"caption":"Veronica hectorii, Fiordland, NZ-SO-SL, NZ-SO, NZ, 2025-01-12 (iNaturalist).","author":"Flavien Saboureau","license":"CC BY 4.0","licenseUrl":"https://creativecommons.org/licenses/by/4.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Veronica_hectorii_-_Flavien_Saboureau_-_463853303.jpeg","articleUrl":"https://en.wikipedia.org/wiki/Veronica_hectorii","retrievedAt":"2026-10-04","focalPoint":"50% 50%","sourceName":"Wikimedia Commons"}]'::jsonb),
  ('veronica-hectorii-v-demissa', 'Veronica hectorii v demissa', null, null, null, 'contested', null, null, false, 'C8', true, 'SP-157', 'C8: Is the demissa variety its own line or folded into the parent?', '{}'::jsonb, '[]'::jsonb),
  ('veronica-odora', 'Veronica odora', null, 'Hebe', null, 'core', false, false, false, null, false, 'SP-158', null, '{"commonName":"Boxwood hebe","maoriNames":[],"nameNote":"Older references may use Hebe odora or Hebe buxifolia. A species-specific Māori name was not verified in the sources checked.","summary":"A compact evergreen native shrub of mountain and subalpine scrub and grassland. Its dense, box-like foliage gives it the common name boxwood hebe.","lookFor":"Short oval leaves, glossy dark green above and paler below, packed closely on the branches. White flowers cluster near the branch tips.","sources":[{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Veronica_odora"}],"checkedOn":"2026-10-04"}'::jsonb, '[{"src":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/50/Veronica_odora_01.jpg/960px-Veronica_odora_01.jpg","width":960,"height":640,"caption":"Veronica odora in Christchurch Botanic Gardens in Christchurch, Canterbury Region, New Zealand.","author":"Krzysztof Golik","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Veronica_odora_01.jpg","articleUrl":"https://en.wikipedia.org/wiki/Veronica_odora","retrievedAt":"2026-10-04","focalPoint":"50% 50%","sourceName":"Wikimedia Commons"},{"src":"https://thumb.wikimedia.org/wikipedia/commons/thumb/c/ca/Veronica_odora_02.jpg/960px-Veronica_odora_02.jpg","width":960,"height":640,"caption":"Veronica odora in Christchurch Botanic Gardens in Christchurch, Canterbury Region, New Zealand.","author":"Krzysztof Golik","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Veronica_odora_02.jpg","articleUrl":"https://en.wikipedia.org/wiki/Veronica_odora","retrievedAt":"2026-10-04","focalPoint":"50% 50%","sourceName":"Wikimedia Commons"},{"src":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4c/Veronica_odora_03.jpg/960px-Veronica_odora_03.jpg","width":960,"height":1440,"caption":"Veronica odora in Christchurch Botanic Gardens in Christchurch, Canterbury Region, New Zealand.","author":"Krzysztof Golik","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Veronica_odora_03.jpg","articleUrl":"https://en.wikipedia.org/wiki/Veronica_odora","retrievedAt":"2026-10-04","focalPoint":"50% 50%","sourceName":"Wikimedia Commons"}]'::jsonb),
  ('veronica-pauciramosa', 'Veronica pauciramosa', null, null, null, 'seedlog_only', null, null, false, null, false, 'SP-159', null, '{}'::jsonb, '[]'::jsonb),
  ('veronica-pimeliodesv-faucola', 'Veronica pimeliodesv faucola', 'Veronica pimeleoides var. faucicola', null, null, 'contested', null, null, false, null, true, 'SP-160', 'C12: Variety written as its own line with no parent line in any list. Own line, or a form of Veronica pimeleoides?', '{}'::jsonb, '[]'::jsonb),
  ('veronica-propinqua', 'Veronica propinqua', null, null, null, 'core', false, false, false, null, false, 'SP-161', null, '{"commonName":"Whipcord hebe","maoriNames":[],"nameNote":"Whipcord hebe is a shared common name for several species. NZPCN accepts Veronica propinqua and lists Hebe propinqua as a synonym. No Māori name was documented in the checked species account.","summary":"An endemic low, spreading whipcord hebe of Otago and Southland mountain grassland and scrub. Its narrow green branchlets carry closely pressed scale leaves, with small groups of white flowers at the tips.","lookFor":"Look for upright or ascending cord-like shoots with overlapping rounded green scales and visible joints between them. Similar whipcord hebes need careful comparison of scales, branchlets and flowers.","sources":[{"label":"New Zealand Plant Conservation Network","url":"https://www.nzpcn.org.nz/flora/species/veronica-propinqua/"}],"checkedOn":"2026-10-04","photoCheck":{"status":"confirmed","reason":"Species-specific sources and three distinct licensed files were checked; selected hosted photos were visually inspected in the browser.","checkedOn":"2026-10-04"}}'::jsonb, '[{"src":"https://inaturalist-open-data.s3.amazonaws.com/photos/456964574/large.jpg","width":768,"height":1024,"caption":"Veronica propinqua spreading whipcord shoots.","author":"Matt Scott","license":"CC BY 4.0","licenseUrl":"https://creativecommons.org/licenses/by/4.0/","sourceUrl":"https://www.inaturalist.org/photos/456964574","articleUrl":"https://www.nzpcn.org.nz/flora/species/veronica-propinqua/","articleLabel":"NZPCN","retrievedAt":"2026-10-04","focalPoint":"50% 50%","sourceName":"iNaturalist","observationUrl":"https://www.inaturalist.org/observations/255041017"},{"src":"https://inaturalist-open-data.s3.amazonaws.com/photos/456964585/large.jpg","width":768,"height":1024,"caption":"Veronica propinqua scale-leaf detail.","author":"Matt Scott","license":"CC BY 4.0","licenseUrl":"https://creativecommons.org/licenses/by/4.0/","sourceUrl":"https://www.inaturalist.org/photos/456964585","articleUrl":"https://www.nzpcn.org.nz/flora/species/veronica-propinqua/","articleLabel":"NZPCN","retrievedAt":"2026-10-04","focalPoint":"50% 50%","sourceName":"iNaturalist","observationUrl":"https://www.inaturalist.org/observations/255041017"},{"src":"https://inaturalist-open-data.s3.amazonaws.com/photos/262748066/large.jpeg","width":1024,"height":771,"caption":"Veronica propinqua low spreading growth.","author":"John Barkla","license":"CC BY 4.0","licenseUrl":"https://creativecommons.org/licenses/by/4.0/","sourceUrl":"https://www.inaturalist.org/photos/262748066","articleUrl":"https://www.nzpcn.org.nz/flora/species/veronica-propinqua/","articleLabel":"NZPCN","retrievedAt":"2026-10-04","focalPoint":"50% 50%","sourceName":"iNaturalist","observationUrl":"https://www.inaturalist.org/observations/152217826"}]'::jsonb),
  ('veronica-rakaiensis', 'Veronica rakaiensis', null, null, null, 'core', false, false, false, null, false, 'SP-162', null, '{"commonName":"Hebe","maoriNames":[],"nameNote":"Hebe is a shared common name. NZPCN lists Hebe rakaiensis as a synonym of Veronica rakaiensis; source photographs using Hebe retain that labelling in captions.","summary":"A bushy South Island shrub often found in upland stream valleys. It usually forms a rounded plant with short narrow leaves and white flower spikes.","lookFor":"Pairs of small glossy leaves widest toward the tip; white flower clusters and minute hairs on leaf margins and capsules.","sources":[{"label":"New Zealand Plant Conservation Network","url":"https://www.nzpcn.org.nz/flora/species/veronica-rakaiensis/"}],"checkedOn":"2026-10-04","photoCheck":{"status":"confirmed","reason":"Species source and three distinct openly licensed images visually checked.","checkedOn":"2026-10-04"}}'::jsonb, '[{"src":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/97/Veronica_rakaiensis_01.jpg/960px-Veronica_rakaiensis_01.jpg","width":960,"height":640,"caption":"Veronica rakaiensis leaf pairs and woody branches.","author":"Krzysztof Golik","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Veronica_rakaiensis_01.jpg","articleUrl":"https://www.nzpcn.org.nz/flora/species/veronica-rakaiensis/","articleLabel":"NZPCN","retrievedAt":"2026-10-04","focalPoint":"50% 50%","sourceName":"Wikimedia Commons"},{"src":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f5/Veronica_rakaiensis_MRD_Otari.jpg/960px-Veronica_rakaiensis_MRD_Otari.jpg","width":960,"height":720,"caption":"Veronica rakaiensis leafy shrub at Ōtari-Wilton’s Bush.","author":"Mike Dickison","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Veronica_rakaiensis_MRD_Otari.jpg","articleUrl":"https://www.nzpcn.org.nz/flora/species/veronica-rakaiensis/","articleLabel":"NZPCN","retrievedAt":"2026-10-04","focalPoint":"50% 50%","sourceName":"Wikimedia Commons"},{"src":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/56/Hebe_rakaiensis.jpg/960px-Hebe_rakaiensis.jpg","width":960,"height":768,"caption":"Veronica rakaiensis white flower spikes, labelled Hebe rakaiensis at source.","author":"Alan Pascoe","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0/","sourceUrl":"https://commons.wikimedia.org/wiki/File:Hebe_rakaiensis.jpg","articleUrl":"https://www.nzpcn.org.nz/flora/species/veronica-rakaiensis/","articleLabel":"NZPCN","retrievedAt":"2026-10-04","focalPoint":"50% 50%","sourceName":"Wikimedia Commons"}]'::jsonb),
  ('veronica-salicifolia', 'Veronica salicifolia', null, 'Koromiko', 'Koromiko', 'core', false, false, false, null, false, 'SP-163', null, '{"commonName":"Willow-leaf hebe","maoriNames":["Koromiko"],"nameNote":"Older references use Hebe salicifolia. Koromiko is shared by several native hebe species.","summary":"An evergreen shrub with a spreading, willow-like appearance. Its long flower spikes provide nectar and pollen for a range of insects.","lookFor":"Long, narrow leaves in opposite pairs, with drooping spikes of white or pale lilac flowers. Seed capsules also hang down rather than standing upright.","sources":[{"label":"Wikipedia","url":"https://en.wikipedia.org/wiki/Veronica_salicifolia"}],"checkedOn":"2026-10-04"}'::jsonb, '[{"src":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/50/Veronica_salicifolia_in_Christchurch_Botanic_Gardens_01.jpg/960px-Veronica_salicifolia_in_Christchurch_Botanic_Gardens_01.jpg","width":960,"height":640,"caption":"Veronica salicifolia in Christchurch Botanic Gardens in Christchurch, Canterbury Region, New Zealand.","author":"Krzysztof Golik","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Veronica_salicifolia_in_Christchurch_Botanic_Gardens_01.jpg","articleUrl":"https://en.wikipedia.org/wiki/Veronica_salicifolia","retrievedAt":"2026-10-04","focalPoint":"50% 50%","sourceName":"Wikimedia Commons"},{"src":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/52/Veronica_salicifolia_in_Aoraki_Mount_Cook_NP_02.jpg/960px-Veronica_salicifolia_in_Aoraki_Mount_Cook_NP_02.jpg","width":960,"height":788,"caption":"Veronica salicifolia at Governor''s Bush Walk in Aoraki/Mount Cook National Park, Canterbury Region, South Island of New Zealand.","author":"Krzysztof Golik","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Veronica_salicifolia_in_Aoraki_Mount_Cook_NP_02.jpg","articleUrl":"https://en.wikipedia.org/wiki/Veronica_salicifolia","retrievedAt":"2026-10-04","focalPoint":"50% 50%","sourceName":"Wikimedia Commons"},{"src":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5b/Veronica_salicifolia_in_Aoraki_Mount_Cook_NP_01.jpg/960px-Veronica_salicifolia_in_Aoraki_Mount_Cook_NP_01.jpg","width":960,"height":1440,"caption":"Veronica salicifolia at Governor''s Bush Walk in Aoraki/Mount Cook National Park, Canterbury Region, South Island of New Zealand.","author":"Krzysztof Golik","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Veronica_salicifolia_in_Aoraki_Mount_Cook_NP_01.jpg","articleUrl":"https://en.wikipedia.org/wiki/Veronica_salicifolia","retrievedAt":"2026-10-04","focalPoint":"50% 50%","sourceName":"Wikimedia Commons"}]'::jsonb),
  ('weinmania-racemosa', 'Weinmania racemosa', 'Weinmannia racemosa', 'Kāmahi', 'Kāmahi', 'core', true, false, false, null, false, 'SP-164', null, '{"commonName":"Kāmahi","maoriNames":["Kāmahi","Tawheo","Tawhero","Tawherowhero"],"nameNote":"The database spelling Weinmania racemosa is retained. Botanical references spell the former name Weinmannia racemosa; NZPCN now accepts Pterophylla racemosa and lists Weinmannia racemosa as its synonym. Tawhero is shared with other trees.","summary":"An endemic forest tree found from coastal areas to subalpine habitats. It can be common in disturbed forest and dominate some higher mountain forests.","lookFor":"Adult leaves usually simple with deeply toothed margins; white or pink flowers gather in narrow spike-like clusters.","sources":[{"label":"New Zealand Plant Conservation Network","url":"https://www.nzpcn.org.nz/flora/species/pterophylla-racemosa/"}],"checkedOn":"2026-10-04","photoCheck":{"status":"confirmed","reason":"Species source and three distinct openly licensed images visually checked.","checkedOn":"2026-10-04"}}'::jsonb, '[{"src":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f0/KamahiFoliage.jpg/960px-KamahiFoliage.jpg","width":960,"height":720,"caption":"Kāmahi young foliage, labelled Weinmannia racemosa at source.","author":"Kahuroa","license":"Public domain","licenseUrl":"https://commons.wikimedia.org/wiki/Commons:Public_domain","sourceUrl":"https://commons.wikimedia.org/wiki/File:KamahiFoliage.jpg","articleUrl":"https://www.nzpcn.org.nz/flora/species/pterophylla-racemosa/","articleLabel":"NZPCN","retrievedAt":"2026-10-04","focalPoint":"50% 50%","sourceName":"Wikimedia Commons"},{"src":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d1/Weinmannia_racemosa_flowers.jpg/960px-Weinmannia_racemosa_flowers.jpg","width":960,"height":1078,"caption":"Kāmahi white flower spikes on the Milford Road.","author":"Alan Liefting","license":"Public domain","licenseUrl":"https://commons.wikimedia.org/wiki/Commons:Public_domain","sourceUrl":"https://commons.wikimedia.org/wiki/File:Weinmannia_racemosa_flowers.jpg","articleUrl":"https://www.nzpcn.org.nz/flora/species/pterophylla-racemosa/","articleLabel":"NZPCN","retrievedAt":"2026-10-04","focalPoint":"50% 50%","sourceName":"Wikimedia Commons"},{"src":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/58/Weinmannia_racemosa_Ulva_Island.JPG/960px-Weinmannia_racemosa_Ulva_Island.JPG","width":960,"height":1285,"caption":"Kāmahi flowering branch on Ulva Island.","author":"MurielBendel","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","sourceUrl":"https://commons.wikimedia.org/wiki/File:Weinmannia_racemosa_Ulva_Island.JPG","articleUrl":"https://www.nzpcn.org.nz/flora/species/pterophylla-racemosa/","articleLabel":"NZPCN","retrievedAt":"2026-10-04","focalPoint":"50% 50%","sourceName":"Wikimedia Commons"}]'::jsonb)
on conflict (slug) do update set
  scientific_name = excluded.scientific_name, suggested_spelling = excluded.suggested_spelling,
  common_name = excluded.common_name, maori_name = excluded.maori_name, status = excluded.status,
  over_5m = excluded.over_5m, threatened = excluded.threatened, threatened_te_kakano = excluded.threatened_te_kakano,
  contested_group = excluded.contested_group, needs_decision = excluded.needs_decision,
  register_code = excluded.register_code, register_note = excluded.register_note,
  profile = case when species.profile = '{}'::jsonb then excluded.profile else species.profile end,
  photos  = case when species.photos  = '[]'::jsonb then excluded.photos  else species.photos  end
  where (species.scientific_name, species.suggested_spelling, species.common_name, species.maori_name, species.status,
         species.over_5m, species.threatened, species.threatened_te_kakano, species.contested_group,
         species.needs_decision, species.register_code, species.register_note)
        is distinct from
        (excluded.scientific_name, excluded.suggested_spelling, excluded.common_name, excluded.maori_name, excluded.status,
         excluded.over_5m, excluded.threatened, excluded.threatened_te_kakano, excluded.contested_group,
         excluded.needs_decision, excluded.register_code, excluded.register_note)
     or (species.profile = '{}'::jsonb and excluded.profile <> '{}'::jsonb)
     or (species.photos  = '[]'::jsonb and excluded.photos  <> '[]'::jsonb);

