insert into public.areas (slug, site, name, description, wrt_number, class, lat, lng, pin_source_url, pin_checked_on) values
  ('arrow-morven', 'arrow-morven', 'Arrow Morven', 'Morven Ferry Reserve is a reference beside the Arrow River and trail at Arrow Junction. The historic register calls this planting group Arrow River Track – Arrow Junction. The exact 2015 planting stretch is not established.', '17', 'community', -44.991, 168.8548, 'https://gis.qldc.govt.nz/server/rest/services/OpenSpaces/Parks_and_Open_Spaces_VIEWER/MapServer/32/query?where=OBJECTID%3D797&outFields=*&outSR=4326&returnGeometry=true&f=pjson', '2026-10-07'),
  ('arrow-river-av', 'arrow-river', 'Arrow River - AV', '', '14', 'community', null, null, null, null),
  ('arrowtown-primary', 'arrowtown-and-bush-creek', 'Arrowtown Primary', 'School grounds at 9 Chalmers Place provide a reference for the Arrowtown Primary records. The individual planting beds are not documented.', '13B', 'school', -44.9486, 168.8393, 'https://www.openstreetmap.org/way/133134846', '2026-10-07'),
  ('bush-creek-arrowtown-preschool', 'arrowtown-and-bush-creek', 'Bush Creek - Arrowtown Preschool', '', '13A', 'school', null, null, null, null),
  ('bush-creek-keystone', 'arrowtown-and-bush-creek', 'Bush Creek Keystone', 'A historic WRT planting-day location near Arrowtown’s Chinese Settlement. The group also includes separate school and reserve locations.', '13C', 'keystone', -44.9373, 168.8276, 'https://www.google.com/maps/d/kml?mid=1xjcJLd9yNvuMP6KkSce-tRHYfHJWQbQ&forcekml=1', '2026-10-07'),
  ('derby-street-reserve', 'arrowtown-and-bush-creek', 'Derby Street Reserve', 'The council-mapped native planting area maintained by the Derby Street Reserve Restoration Group. Historical records are assigned to the Derby Street sub-site.', '13D', 'community', -44.9423, 168.8289, 'https://gis.qldc.govt.nz/server/rest/services/OpenSpaces/Parks_and_Open_Spaces_VIEWER/MapServer/40/query?where=OBJECTID%3D1776&outFields=%2A&outSR=4326&returnGeometry=true&f=pjson', '2026-10-07'),
  ('arrowtown-preschool', 'arrowtown-preschool', 'Arrowtown Preschool', '', null, 'school', null, null, null, null),
  ('arthurs-point-atley-downs', 'arthurs-point', 'Arthurs Point - Atley Downs', 'A public reserve reference in the Atley Downs area. The historic planting records do not identify the individual planting patch.', '6', 'community', -44.9861, 168.6764, 'https://gis.qldc.govt.nz/server/rest/services/OpenSpaces/Parks_and_Open_Spaces_VIEWER/MapServer/32/query?where=OBJECTID%3D393&outFields=%2A&outSR=4326&returnGeometry=true&f=pjson', '2026-10-07'),
  ('arthurs-point-doc-office', 'arthurs-point', 'Arthurs Point - DOC Office', 'The Cavells Building at 1 Arthurs Point Road is a landmark for the DOC Office planting records. It does not locate individual planting beds.', '6A', 'community', -44.9876, 168.6721, 'https://maps.app.goo.gl/EW6RH5P4npyXG5uHA', '2026-10-07'),
  ('arthurs-point-morning-star-reserve', 'arthurs-point', 'Arthurs Point - Morning Star Reserve', 'A broad reference for Morning Star Beach Recreation Reserve beside the Shotover River. WRT-supported planting occupies a plateau within the reserve; this point does not mark the plateau or an entrance.', '6B', 'community', -44.9809, 168.6679, 'https://api.inaturalist.org/v1/places/89383', '2026-10-07'),
  ('bridesdale', 'bridesdale', 'Bridesdale', 'A reference within a council-mapped Bridesdale Bush Trust planting area on Hayes Creek Road. Council identifies the wider restoration project as supported by WRT. The individual planting patch behind the ledger’s Bridesdale records is not established.', null, 'community', -45.0036, 168.799, 'https://gis.qldc.govt.nz/server/rest/services/OpenSpaces/Parks_and_Open_Spaces_VIEWER/MapServer/40/query?where=OBJECTID%3D1748&outFields=*&outSR=4326&returnGeometry=true&f=pjson', '2026-10-07'),
  ('feehly-hill-cemetery', 'feehly-hill', 'Feehly Hill - Cemetery', 'The cemetery is a landmark for WRT plantings on the hillside behind it. Additional planting areas lie near Manse Road and the Powder Magazine.', '12A', 'keystone', -44.9399, 168.827, 'https://gis.qldc.govt.nz/server/rest/services/OpenSpaces/Cemeteries/MapServer/4/query?where=OBJECTID%3D384&outFields=*&outSR=4326&returnGeometry=true&f=pjson', '2026-10-07'),
  ('feehly-hill-magazine', 'feehly-hill', 'Feehly Hill - Magazine', 'The historic Powder Magazine beside Malaghans Road is a landmark for the Magazine planting area at the foot of Feehly Hill.', '12', 'community', -44.9423, 168.8277, 'https://www.heritage.org.nz/list-details/2108/Listing', '2026-10-07'),
  ('feehly-hill-manse-rd', 'feehly-hill', 'Feehly Hill - Manse Rd', 'Manse Road Reserve is a reference on the western side of Feehly Hill. The exact historical planting patches remain unconfirmed.', '12B', 'community', -44.9388, 168.8203, 'https://gis.qldc.govt.nz/server/rest/services/OpenSpaces/Parks_and_Open_Spaces_VIEWER/MapServer/32/query?where=OBJECTID%3D745&outFields=%2A&outSR=4326&returnGeometry=true&f=pjson', '2026-10-07'),
  ('gibbston-community-reserve', 'gibbston', 'Gibbston Community / Reserve', 'The community reserve on Coal Pit Road is the named location in the planting ledger. This marker is a reserve reference point rather than a mapped planting patch.', '27', 'community', -45.0253, 168.9553, 'https://gis.qldc.govt.nz/server/rest/services/OpenSpaces/Parks_VIEWER/MapServer/31/query?where=OBJECTID%3D548&outFields=OBJECTID%2CSITENME&outSR=4326&returnGeometry=true&f=pjson', '2026-10-07'),
  ('glenorchy-bible-terrace', 'glenorchy', 'Glenorchy Bible Terrace', '', '1D', 'community', null, null, null, null),
  ('glenorchy-entrance', 'glenorchy', 'Glenorchy Entrance', '', '1B', 'community', null, null, null, null),
  ('glenorchy-lagoon-walkway', 'glenorchy', 'Glenorchy Lagoon & Walkway', 'A public reference point on the lagoon walkway near Glenorchy’s waterfront. Historical lagoon and walkway planting extends around the wetlands beyond this point.', '1', 'community', -44.8499, 168.3823, 'https://scd.landcareresearch.co.nz/Specimen/PDD%20108570', '2026-10-07'),
  ('glenorchy-lakefront', 'glenorchy', 'Glenorchy Lakefront', 'The wharf is a landmark beside Glenorchy’s lakefront planting area. The marker shows the wharf and does not map individual shoreline planting patches.', '1C', 'community', -44.8515, 168.3815, 'https://www.openstreetmap.org/way/1289096084', '2026-10-07'),
  ('glenorchy-school', 'glenorchy', 'Glenorchy School', 'The school on Oban Street is a separate part of Glenorchy’s planting history. This marker locates the school grounds rather than its planting patch.', '1A', 'school', -44.8507, 168.387, 'https://www.openstreetmap.org/way/466602386', '2026-10-07'),
  ('pigeon-island', 'glenorchy', 'Pigeon Island', 'The island in northern Lake Whakatipu is a separate part of the Glenorchy planting history. This broad island reference does not show the restoration plots or landing points.', '1E', 'community', -44.9227, 168.3965, 'https://gis.qldc.govt.nz/server/rest/services/OpenSpaces/Parks_VIEWER/MapServer/31/query?where=OBJECTID%3D873&outFields=OBJECTID%2CSITENME&outSR=4326&returnGeometry=true&f=pjson', '2026-10-07'),
  ('1-mile-creek', 'gorge-road-area', '1 Mile Creek', '', '5C', 'community', null, null, null, null),
  ('alpine-retreat', 'gorge-road-area', 'Alpine Retreat', 'A road reference within the Alpine Retreat community, accessed via Moke Lake Road. Restoration extends onto shared common land nearby.', '5D', 'community', -45.0466, 168.5966, 'https://www.openstreetmap.org/way/223291862', '2026-10-07'),
  ('ben-lomond-zip-trek', 'gorge-road-area', 'Ben Lomond / Zip Trek', 'A reference point within Ziptrek’s tour area above Queenstown, where WRT-supported restoration has taken place. Individual planting patches are not shown.', '5E', 'community', -45.0282, 168.6517, 'https://www.google.com/maps/d/kml?mid=19fTsCPTo5LpPkFS6bYNkwVrX1Xo&forcekml=1', '2026-10-07'),
  ('gorge-rd-harvest-garden', 'gorge-road-area', 'Gorge Rd Harvest Garden', 'The gardens at 201 Gorge Road have native planting along their southern fence. The marker shows a nearby address reference.', '5B', 'community', -45.014, 168.6666, 'https://www.openstreetmap.org/node/12009361230', '2026-10-07'),
  ('gorge-rd-wetlands', 'gorge-road-area', 'Gorge Rd Wetlands', '', '5', 'community', null, null, null, null),
  ('the-rees', 'gorge-road-area', 'The Rees', 'A council-mapped community planting area on the Frankton Track below The Rees Hotel. This is one of several separate places grouped under Gorge Road area.', '5F', 'community', -45.0286, 168.6891, 'https://gis.qldc.govt.nz/server/rest/services/OpenSpaces/Parks_and_Open_Spaces_VIEWER/MapServer/40/query?where=OBJECTID%3D10506&outFields=*&outSR=4326&returnGeometry=true&f=pjson', '2026-10-07'),
  ('hidden-island-cecil-peak', 'hidden-island-and-cecil-peak', 'Hidden Island / Cecil Peak', '', '30', 'community', null, null, null, null),
  ('jardine-boulders', 'jardine-boulders', 'Jardine Boulders', 'A reference for the named boulder field on Remarkables Station, beside SH6. The exact position of the ledger’s native plantings within this area has not been established.', '25', 'community', -45.0958, 168.7649, 'https://www.thecrag.com/en/climbing/new-zealand/queenstown/area/1484755365', '2026-10-07'),
  ('jardine-park-jmn-reference-gardens', 'jardine-park', 'Jardine Park - JMN Reference Gardens', 'Jean Malpas Community Nursery on Poplar Drive is a navigation reference for the surrounding native Reference Gardens. The marker identifies the nursery venue, rather than the boundary of the planted gardens.', '23', 'keystone', -45.0454, 168.6941, 'https://www.eventbrite.co.nz/e/community-nursery-volunteer-sessions-tickets-1998116193322', '2026-10-07'),
  ('jardine-park-track-entrance', 'jardine-park', 'Jardine Park - Track Entrance', '', '23A', 'keystone', null, null, null, null),
  ('jardine-park-welcome-forest', 'jardine-park', 'Jardine Park - Welcome Forest', 'A council-mapped WRT native planting area in the southern part of Jardine Park. The council development plan identifies Welcome Forest plantings here. This point represents one planting patch, rather than the full forest boundary.', '23B', 'keystone', -45.0476, 168.6888, 'https://gis.qldc.govt.nz/server/rest/services/OpenSpaces/Parks_and_Open_Spaces_VIEWER/MapServer/40/query?where=OBJECTID%3D1778&outFields=*&outSR=4326&returnGeometry=true&f=pjson', '2026-10-07'),
  ('kelvin-peninsula-corner', 'kelvin-peninsula', 'Kelvin Peninsula - Corner', '', '22C', 'keystone', null, null, null, null),
  ('kelvin-peninsula-golf-course', 'kelvin-peninsula', 'Kelvin Peninsula - Golf Course', 'Queenstown Golf Club occupies the head of Kelvin Peninsula. This is a broad course reference for the golf-course planting records; it does not identify which hole or planting area.', '22B', 'keystone', -45.043, 168.6708, 'https://www.openstreetmap.org/way/89381653', '2026-10-07'),
  ('kelvin-peninsula-kpca', 'kelvin-peninsula', 'Kelvin Peninsula - KPCA', '', '22', 'keystone', null, null, null, null),
  ('kelvin-peninsula-slipway-project-crimson', 'kelvin-peninsula', 'Kelvin Peninsula - Slipway / Project Crimson', 'The Earnslaw Slipway reserve is the named landmark for the Slipway / Project Crimson planting records. This reference point covers that part of the ledger only.', '22A', 'keystone', -45.0404, 168.6767, 'https://gis.qldc.govt.nz/server/rest/services/OpenSpaces/Parks_VIEWER/MapServer/23/query?where=OBJECTID%3D10516&outFields=OBJECTID%2CSITENME&outSR=4326&returnGeometry=true&f=pjson', '2026-10-07'),
  ('kingston-community', 'kingston', 'Kingston Community', '', '26', 'community', null, null, null, null),
  ('kingsview', 'kingsview', 'Kingsview', 'KingsView School at 14 Yewlett Crescent, Frankton, is a reference for the school planting records. The marker identifies the school rather than an individual planting patch.', null, 'school', -45.0177, 168.7279, 'https://www.openstreetmap.org/way/384923492', '2026-10-07'),
  ('kiwi-park', 'kiwi-park', 'Kiwi Park', 'A reference within Kiwi Park, the wildlife sanctuary on Brecon Street below the gondola. It marks the park grounds rather than an individual planting area. Visitor entry is managed by the park.', null, 'community', -45.0274, 168.6571, 'https://www.openstreetmap.org/way/248085277', '2026-10-07'),
  ('lake-hayes-east-rowing-club', 'lake-hayes', 'Lake Hayes East - Rowing Club', 'A reference among the council-mapped planting areas beside Whakatipu Rowing Club on the eastern shore. The current mapped areas are a landmark for this ledger part, rather than its historical planting boundary.', '9H', 'keystone', -44.988, 168.8119, 'https://gis.qldc.govt.nz/server/rest/services/OpenSpaces/Parks_and_Open_Spaces_VIEWER/MapServer/40/query?where=OBJECTID+IN+%281749%2C1751%2C1781%2C10001%29&outFields=OBJECTID%2CSITENME%2CROAD%2CSUBLOC%2CNOTES&outSR=4326&returnGeometry=true&f=pjson', '2026-10-07'),
  ('lake-hayes-green-cabs', 'lake-hayes', 'Lake Hayes Green Cabs', '', '9E', 'community', null, null, null, null),
  ('lake-hayes-north-akarua-corner', 'lake-hayes', 'Lake Hayes North - Akarua Corner', '', '9F', 'community', null, null, null, null),
  ('lake-hayes-pavilion', 'lake-hayes', 'Lake Hayes Pavilion', 'A reference within a council-mapped WRT planting area below Lake Hayes Pavilion. The council records first planting here in spring 2023. The current footprint does not define the full historical planting boundary.', '9G', 'keystone', -44.9907, 168.8082, 'https://gis.qldc.govt.nz/server/rest/services/OpenSpaces/Parks_and_Open_Spaces_VIEWER/MapServer/40/query?where=OBJECTID%3D1844&outFields=OBJECTID%2CSITENME%2CROAD%2CSUBLOC%2CNOTES&outSR=4326&returnGeometry=true&f=pjson', '2026-10-07'),
  ('lake-hayes-rutherford-rd', 'lake-hayes', 'Lake Hayes Rutherford Rd', '', '9D', 'community', null, null, null, null),
  ('lake-hayes-south-roadside', 'lake-hayes', 'Lake Hayes South / Roadside', 'A reference within the council-mapped Lake Hayes South planting area beside the highway. The council identifies it as a WRT keystone site. This current footprint does not define the historical planting boundary.', '9A', 'keystone', -44.9949, 168.8019, 'https://gis.qldc.govt.nz/server/rest/services/OpenSpaces/Parks_and_Open_Spaces_VIEWER/MapServer/40/query?where=OBJECTID%3D1845&outFields=OBJECTID%2CSITENME%2CROAD%2CSUBLOC%2CNOTES&outSR=4326&returnGeometry=true&f=pjson', '2026-10-07'),
  ('lake-hayes-west-pg', 'lake-hayes', 'Lake Hayes West PG', 'A reference within a current council-mapped Project Gold planting area on the western Lake Hayes trail. The historical West PG planting boundary is not verified.', '9', 'keystone', -44.9758, 168.8041, 'https://gis.qldc.govt.nz/server/rest/services/OpenSpaces/Parks_and_Open_Spaces_VIEWER/MapServer/40/query?where=OBJECTID%3D1854&outFields=OBJECTID%2CSITENME%2CROAD%2CSUBLOC%2CNOTES&outSR=4326&returnGeometry=true&f=pjson', '2026-10-07'),
  ('lake-hayes-estate-widgeon-place', 'lake-hayes-estate', 'Lake Hayes Estate - Widgeon Place', 'A reference within Widgeon Park below Lake Hayes Estate. Native planting at the base of Widgeon Place is documented by the residents association. The separate Lake Hayes Estate Trail records are not located by this marker.', '10', 'community', -45.0078, 168.7941, 'https://gis.qldc.govt.nz/server/rest/services/OpenSpaces/Parks_and_Open_Spaces_VIEWER/MapServer/32/query?where=OBJECTID%3D1051&outFields=*&outSR=4326&returnGeometry=true&f=pjson', '2026-10-07'),
  ('lake-hayes-estate-trail', 'lake-hayes-estate', 'Lake Hayes Estate Trail', '', '10A', 'community', null, null, null, null),
  ('little-difference', 'little-difference', 'Little Difference', '', null, 'community', null, null, null, null),
  ('lower-shotover-conservation-area', 'lower-shotover-conservation-area', 'Lower Shotover Conservation Area', 'A reference point inside the DOC conservation area along the Shotover River east of Arthurs Point. The historic planting patch is unknown; this marker represents the named reserve rather than its planting boundary.', '8', 'community', -44.9877, 168.728, 'https://services1.arcgis.com/3JjYDyG3oajxU6HO/arcgis/rest/services/DOC_Public_Conservation_Land/FeatureServer/0/query?where=NaPALIS_ID%3D2804651&outFields=%2A&outSR=4326&returnGeometry=true&f=geojson', '2026-10-07'),
  ('matakauri-wetlands', 'matakauri-wetlands', 'Matakauri Wetlands', 'The published centre of Matakauri Wetland, east of Gorge Road and Industrial Place. It represents the wider wetland; the particular 2026 planting area and an entrance are not established.', null, 'school', -45.0169, 168.6656, 'https://www.orc.govt.nz/environment/water-care/wetlands-and-estuaries/regionally-significant-wetlands/queenstown-lakes-district/matakauri-wetland', '2026-10-07'),
  ('moke-lake-camp', 'moke-lake', 'Moke Lake Camp', 'DOC’s published campsite location corresponds to the ledger’s Moke Lake Camp name. It is a campsite reference rather than the exact position of the historic plantings.', '2', 'community', -44.9981, 168.5731, 'https://www.doc.govt.nz/parks-and-recreation/places-to-go/otago/places/queenstown-area/things-to-do/moke-lake-campsite/', '2026-10-07'),
  ('paererewa', 'paererewa', 'Paererewa', '', null, 'community', null, null, null, null),
  ('paper4trees', 'paper4trees', 'Paper4Trees', '', null, null, null, null, null, null),
  ('boyes-cres', 'peace-park-and-frankton', 'Boyes Cres', 'The council-mapped native planting area cared for by Boyes Crescent residents, separate from the Peace Park planting area.', '21B', 'community', -45.0239, 168.7323, 'https://gis.qldc.govt.nz/server/rest/services/OpenSpaces/Parks_and_Open_Spaces_VIEWER/MapServer/40/query?where=OBJECTID%3D1772&outFields=%2A&outSR=4326&returnGeometry=true&f=pjson', '2026-10-07'),
  ('frankton-beach', 'peace-park-and-frankton', 'Frankton Beach', 'A broad reference within Frankton Domain beside the beach. The Frankton Beach planting records do not identify individual shoreline planting patches.', '21A', 'keystone', -45.0206, 168.7298, 'https://gis.qldc.govt.nz/server/rest/services/OpenSpaces/Parks_and_Open_Spaces_VIEWER/MapServer/32/query?where=OBJECTID%3D1165&outFields=%2A&outSR=4326&returnGeometry=true&f=pjson', '2026-10-07'),
  ('peace-park', 'peace-park-and-frankton', 'Peace Park', 'A council-mapped WRT restoration area on the Frankton foreshore. This reference point does not include the separate Frankton Beach and Boyes Crescent areas.', '21', 'keystone', -45.0253, 168.7317, 'https://gis.qldc.govt.nz/server/rest/services/OpenSpaces/Parks_and_Open_Spaces_VIEWER/MapServer/40/query?where=OBJECTID%3D6401&outFields=*&outSR=4326&returnGeometry=true&f=pjson', '2026-10-07'),
  ('qldc-tohu', 'qldc-tohu', 'QLDC Tohu', '', null, 'community', null, null, null, null),
  ('quail-rise', 'quail-rise', 'Quail Rise', 'WRT’s historic planting-day pin for the Jim’s Way community restoration area at Quail Rise. Planting extends along the reserve beyond this point.', '29', 'community', -45.0003, 168.7546, 'https://www.google.com/maps/d/kml?mid=1xjcJLd9yNvuMP6KkSce-tRHYfHJWQbQ&forcekml=1', '2026-10-07'),
  ('kerry-drive-reserve', 'queenstown-hill-and-primary', 'Kerry Drive Reserve', 'A reference within the council-mapped Kerry Drive Reserve. This marker covers the Kerry Drive records; Queenstown Hill and the primary school are separate parts of the ledger group.', '4B', 'community', -45.0284, 168.6657, 'https://gis.qldc.govt.nz/server/rest/services/OpenSpaces/Parks_and_Open_Spaces_VIEWER/MapServer/32/query?where=OBJECTID%3D659&outFields=*&outSR=4326&returnGeometry=true&f=pjson', '2026-10-07'),
  ('queenstown-hill', 'queenstown-hill-and-primary', 'Queenstown Hill', '', '4A', 'community', null, null, null, null),
  ('queenstown-primary-school', 'queenstown-hill-and-primary', 'Queenstown Primary School', 'The school at 20 Robins Road is a reference for the school-ground planting records. The marker does not locate individual school planting patches. Visit arrangements belong to the school.', '4', 'school', -45.0276, 168.6587, 'https://www.openstreetmap.org/way/150605658', '2026-10-07'),
  ('rapley-close', 'rapley-close', 'Rapley Close', '', '16', 'community', null, null, null, null),
  ('shotover-primary-internal-planting', 'shotover-primary', 'Shotover Primary - Internal planting', 'The school at 57 Stalker Road is a reference for internal school planting records. The separate Shotover Wetland marker covers wetland planting.', '20B', 'school', -45.0059, 168.7765, 'https://www.otagocdem.govt.nz/media/1173/shotover-and-lake-hayes-community-response-plan.pdf', '2026-10-07'),
  ('shotover-primary-wetlands', 'shotover-primary', 'Shotover Primary - Wetlands', 'A reference within the council’s wetland and recreation zone east of the Shotover–Kawarau confluence. Most Shotover Primary records relate to this wetland, with separate planting on school grounds.', '20A', 'school', -45.0109, 168.7735, 'https://gis.qldc.govt.nz/server/rest/services/Planning/Structure_Plans/MapServer/58/query?where=OBJECTID%3D448&outFields=*&outSR=4326&returnGeometry=true&f=pjson', '2026-10-07'),
  ('shotover-rotary-track', 'shotover-rotary-track', 'Shotover Rotary Track', 'The start of the Rotary Tucker Beach Trail near the Old Lower Shotover Bridge is a navigation landmark for planting along the trail. The planting history does not identify a particular section of this 3.2 km route.', null, 'community', -44.9973, 168.7562, 'https://gis.qldc.govt.nz/server/rest/services/OpenSpaces/Parks_VIEWER/MapServer/57/query?where=OBJECTID%3D6804&outFields=OBJECTID%2CSITENME&outSR=4326&returnGeometry=true&f=pjson', '2026-10-07'),
  ('skippers-doc', 'skippers-doc', 'Skippers - DOC', '', null, 'community', null, null, null, null),
  ('slope-hill-coronation', 'slope-hill', 'Slope Hill Coronation', '', '11A', 'keystone', null, null, null, null),
  ('slope-hill-hgf', 'slope-hill', 'Slope Hill HGF', '', null, 'keystone', null, null, null, null),
  ('slope-hill-road', 'slope-hill', 'Slope Hill Road', 'A historic WRT planting-day location beside the creek and cycle trail, accessed from Speargrass Flat Road along Slope Hill Road. Its count covers the Road planting part; the separate Coronation and HGF areas remain unlocated.', '11', 'keystone', -44.9716, 168.7985, 'https://www.google.com/maps/d/kml?mid=1xjcJLd9yNvuMP6KkSce-tRHYfHJWQbQ&forcekml=1', '2026-10-07'),
  ('kawarau-bridge', 'swiftburn-and-kawarau-bridge', 'Kawarau Bridge', 'The historic AJ Hackett bungy bridge is the landmark named in the Kawarau Bridge records. Swiftburn plantings are a separate ledger part and are not counted at this marker.', '18A', 'community', -45.009, 168.899, 'https://d2rjvl4n5h2b61.cloudfront.net/media/documents/kawarau_gorge_suspension_bridgereport.pdf', '2026-10-07'),
  ('swiftburn', 'swiftburn-and-kawarau-bridge', 'Swiftburn', '', '18', 'community', null, null, null, null),
  ('shotover-river', 'tucker-beach-and-shotover-river', 'Shotover River', '', null, 'community', null, null, null, null),
  ('tucker-beach-and-shotover-river-shotover-river', 'tucker-beach-and-shotover-river', 'Shotover River', '', '28A', 'community', null, null, null, null),
  ('tucker-beach', 'tucker-beach-and-shotover-river', 'Tucker Beach', 'WRT’s historic community planting-day location within Tucker Beach Wildlife Reserve. Separate Shotover River ledger parts have not been assigned to this marker.', '28', 'community', -44.9821, 168.7406, 'https://www.google.com/maps/d/kml?mid=1xjcJLd9yNvuMP6KkSce-tRHYfHJWQbQ&forcekml=1', '2026-10-07'),
  ('walter-peak-station', 'walter-peak-station', 'Walter Peak Station', 'Beach Point campsite and public lakeshore walkway are landmarks for the wider Walter Peak restoration area. The historic WRT planting was on adjacent DOC land; this point does not identify the individual planting patch.', null, 'community', -45.1034, 168.5415, 'https://www.doc.govt.nz/documents/parks-and-recreation/places-to-stay/campsite-information/campsites-otago.pdf', '2026-10-07'),
  ('whitechapel-reserve', 'whitechapel', 'Whitechapel Reserve', 'WRT’s historic planting-day location on Whitechapel Road, Arrow Junction, beside the Queenstown Trail. The reserve’s planting areas extend beyond this reference point.', '15', 'keystone', -44.9736, 168.8546, 'https://www.google.com/maps/d/kml?mid=1xjcJLd9yNvuMP6KkSce-tRHYfHJWQbQ&forcekml=1', '2026-10-07'),
  ('wye-creek-climbing-area', 'wye-creek', 'Wye Creek Climbing Area', 'A climbing-area reference near Main Wall, where Queenstown Climbing Club describes its native bush restoration work. Plantings extend around the climbing area; the marker is not a planting boundary or a car park.', '24', 'community', -45.1419, 168.7699, 'https://www.thecrag.com/en/climbing/new-zealand/queenstown/wye-creek/route/13862503', '2026-10-07')
