insert into public.questions (slug, question) values
  ('slope-hill-2024', 'Slope Hill 2024 columns: Were the 22,000 Slope Hill HGF and 7,000 Coronation plants real plantings, and should they count?'),
  ('contested-species', 'Contested species pairs: Are these names one species line or two? Each name is kept as typed until WRT rules.'),
  ('order-scheme', 'Paper4Trees is an order scheme: Paper4Trees is a scheme, not a place. How should its plants count?'),
  ('site-number-mismatch', 'Site number disagrees with the register: The MASTER column carries a different site number from the register. Which one is right?'),
  ('new-site', 'Site with no WRT number: Is this a new site, and what number should it get?'),
  ('site-identity', 'Uncertain site: The column header does not say clearly which site or parcel it means.'),
  ('header-cleaned', 'Site header carried extra text: Confirm the cleaned site name is the right site.'),
  ('not-a-number', 'Cell is not a number: The cell holds text such as ''TBC''. No quantity was imported.'),
  ('other', 'Other check: See the note on each record.')
